// The update log (updates.ts) in every language: updates 34 to 41. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES5: Readonly<Record<string, Row>> = {
  "Lanterns up high, and hills that hide what's behind them": ["高いところのランタンと、向こうを隠す丘", "높이 달린 랜턴, 그리고 뒤를 가리는 언덕", "高悬的灯笼，以及能遮住后方的山丘", "高懸的燈籠，以及能遮住後方的山丘", "Đèn lồng treo cao, và đồi che khuất những gì phía sau", "Lentera di tempat tinggi, dan bukit yang menyembunyikan yang di baliknya", "โคมไฟแขวนสูง และเนินที่บังสิ่งที่อยู่ข้างหลัง", "Yükseğe asılı fenerler ve arkasını saklayan tepeler", "Faroles en lo alto y colinas que tapan lo que hay detrás", "Lanternas no alto e colinas que escondem o que está atrás", "Фонари повыше и холмы, скрывающие то, что за ними", "Ліхтарі вище й пагорби, що ховають те, що за ними"],
  "Lanterns and chandeliers hang higher, up in the rafters, and one that would sit in front of your Friend's face turns see-through.": ["ランタンとシャンデリアは梁の高い位置に吊るされ、フレンドの顔の前に来るものは透けて見えるように。", "랜턴과 샹들리에가 서까래 위로 더 높이 달리고, 프렌드 얼굴 앞을 가리는 건 반투명해집니다.", "灯笼和吊灯挂得更高，在椽子上；挡在伙伴脸前的那盏会变成半透明。", "燈籠和吊燈掛得更高，在椽子上；擋在夥伴臉前的那盞會變成半透明。", "Đèn lồng và đèn chùm treo cao hơn, trên xà nhà, và cái nào che trước mặt Bạn sẽ trở nên trong suốt.", "Lentera dan lampu gantung tergantung lebih tinggi, di kasau, dan yang menutupi wajah Sahabatmu menjadi tembus pandang.", "โคมไฟและโคมระย้าแขวนสูงขึ้นบนขื่อ และอันที่บังหน้าเพื่อนจะโปร่งใส", "Fenerler ve avizeler kirişlerde daha yükseğe asılı; Dostunun yüzünün önüne gelen saydamlaşıyor.", "Faroles y lámparas cuelgan más altos, en las vigas, y el que quedaría delante de la cara de tu Amigo se vuelve transparente.", "Lanternas e lustres ficam mais altos, nas vigas, e o que ficaria na frente do rosto do seu Amigo fica transparente.", "Фонари и люстры висят выше, под стропилами, а тот, что оказался бы перед лицом Друга, становится прозрачным.", "Ліхтарі й люстри висять вище, під кроквами, а той, що опинився б перед обличчям Друга, стає прозорим."],
  "Snowy slopes and hills cover whatever stands behind them: Friends, other players, monsters and houses no longer show through the snow around Highcairn (or any other hill).": ["雪の斜面や丘はその後ろにあるものを隠すように：ハイケアン周辺（やほかの丘）で、フレンドやほかのプレイヤー、モンスター、家が雪越しに透けて見えなくなりました。", "눈 덮인 비탈과 언덕이 뒤에 있는 것을 가립니다: 하이케언 주변(이나 다른 언덕)의 눈 너머로 프렌드, 다른 플레이어, 몬스터, 집이 비쳐 보이지 않습니다.", "雪坡和山丘会遮住身后的东西：高冢周围（或任何山丘）的伙伴、其他玩家、怪物和房屋不再透过雪地显示出来。", "雪坡和山丘會遮住身後的東西：高塚周圍（或任何山丘）的夥伴、其他玩家、怪物和房屋不再透過雪地顯示出來。", "Sườn tuyết và đồi che khuất những gì phía sau: Bạn, người chơi khác, quái vật và nhà cửa không còn hiện xuyên qua tuyết quanh Highcairn (hay bất kỳ ngọn đồi nào).", "Lereng bersalju dan bukit menutupi apa pun di baliknya: Sahabat, pemain lain, monster, dan rumah tak lagi tampak menembus salju di sekitar Highcairn (atau bukit lain).", "ลาดหิมะและเนินเขาบังสิ่งที่อยู่ข้างหลัง: เพื่อน ผู้เล่นอื่น มอนสเตอร์ และบ้าน ไม่โผล่ทะลุหิมะรอบไฮแคร์น (หรือเนินอื่น) อีก", "Karlı yamaçlar ve tepeler ardında duranı örtüyor: Highcairn'in (ya da başka bir tepenin) çevresindeki karın içinden artık Dostlar, diğer oyuncular, canavarlar ve evler görünmüyor.", "Las laderas nevadas y las colinas tapan lo que hay detrás: Amigos, otros jugadores, monstruos y casas ya no se transparentan a través de la nieve de Highcairn (ni de ninguna otra colina).", "Encostas nevadas e colinas cobrem o que está atrás: Amigos, outros jogadores, monstros e casas não aparecem mais através da neve em volta de Highcairn (ou de qualquer colina).", "Снежные склоны и холмы закрывают то, что за ними: Друзья, другие игроки, монстры и дома больше не просвечивают сквозь снег у Хайкэрна (и любого другого холма).", "Засніжені схили й пагорби закривають те, що за ними: Друзі, інші гравці, монстри й будинки більше не просвічують крізь сніг біля Гайкерна (і будь-якого іншого пагорба)."],
  "Friends standing beside Hollow Square's fountain no longer clip into its rim.": ["ホロウ広場の噴水のそばに立つフレンドが、縁にめり込まなくなりました。", "할로우 광장 분수 옆에 선 프렌드가 더 이상 가장자리에 파묻히지 않습니다.", "站在空谷广场喷泉旁的伙伴不再穿进喷泉边沿。", "站在空谷廣場噴泉旁的夥伴不再穿進噴泉邊沿。", "Bạn đứng cạnh đài phun nước Quảng trường Hollow không còn lẹm vào thành bể.", "Sahabat yang berdiri di samping air mancur Alun-alun Hollow tak lagi menembus pinggirannya.", "เพื่อนที่ยืนข้างน้ำพุจัตุรัสฮอลโลว์ไม่จมเข้าไปในขอบอีก", "Hollow Meydanı'nın çeşmesinin yanında duran Dostlar artık kenarına gömülmüyor.", "Los Amigos junto a la fuente de la Plaza Hollow ya no se meten en su borde.", "Amigos ao lado da fonte da Praça Hollow não entram mais na borda.", "Друзья у фонтана на Площади Холлоу больше не проваливаются в его бортик.", "Друзі біля фонтана на Площі Голлоу більше не провалюються в його бортик."],
  "The Stealth update, lamplit rooms, mastery capes and a new fountain": ["隠密アップデート、ランプの灯る部屋、マスターマント、新しい噴水", "은신술 업데이트, 등불 켜진 방, 마스터리 망토, 새 분수", "潜行术更新、灯光照亮的房间、精通披风和新喷泉", "潛行術更新、燈光照亮的房間、精通披風和新噴泉", "Bản cập nhật Ẩn thân, phòng thắp đèn, áo choàng tinh thông và đài phun nước mới", "Pembaruan Siluman, ruangan berlampu, jubah penguasaan, dan air mancur baru", "อัปเดตลอบเร้น ห้องที่มีตะเกียง ผ้าคลุมความเชี่ยวชาญ และน้ำพุใหม่", "Gizlilik güncellemesi, lambalı odalar, ustalık pelerinleri ve yeni bir çeşme", "La actualización del Sigilo, salas iluminadas, capas de maestría y una fuente nueva", "A atualização da Furtividade, salas iluminadas, capas de maestria e uma fonte nova", "Обновление Скрытности, комнаты с лампами, плащи мастерства и новый фонтан", "Оновлення Скритності, кімнати з лампами, плащі майстерності й новий фонтан"],
  "Thieving is now Stealth. Your levels and XP carry over, and pickpocketing and the Oasis stalls are part of it.": ["盗みは「隠密」になりました。レベルと経験値は引き継がれ、スリやオアシスの露店もその一部です。", "도둑질이 이제 은신술이 되었습니다. 레벨과 경험치는 이어지며, 소매치기와 오아시스 노점도 여기에 속합니다.", "偷窃现在改名为潜行术。你的等级和经验都会保留，扒窃和绿洲摊位也归入其中。", "偷竊現在改名為潛行術。你的等級和經驗都會保留，扒竊和綠洲攤位也歸入其中。", "Trộm cắp giờ là Ẩn thân. Cấp và XP được giữ lại, và móc túi cùng các sạp ở Ốc đảo thuộc về nó.", "Mencuri kini menjadi Siluman. Level dan XP-mu tetap, dan mencopet serta kios Oasis termasuk di dalamnya.", "การขโมยตอนนี้เป็นลอบเร้น เลเวลและ XP ยังอยู่ และการล้วงกระเป๋ากับแผงร้านในโอเอซิสเป็นส่วนหนึ่งของมัน", "Hırsızlık artık Gizlilik. Seviyelerin ve XP'n aktarılıyor; yankesicilik ve Vaha tezgâhları da bunun parçası.", "Robar pasa a ser Sigilo. Tus niveles y XP se conservan, y el carterismo y los puestos del Oasis forman parte de él.", "Roubar agora é Furtividade. Seus níveis e XP continuam, e bater carteiras e as barracas do Oásis fazem parte dela.", "Воровство теперь называется Скрытностью. Уровни и опыт сохраняются, а карманные кражи и лотки Оазиса — её часть.", "Крадіжка тепер називається Скритністю. Рівні й досвід зберігаються, а кишенькові крадіжки та ятки Оазису — її частина."],
  "Sneak (the hooded button beside your run energy, or C): walk softly past aggressive monsters. Each tick they may notice you (their level against your Stealth, how close you are, whether you're moving). Slip out of reach unseen for Stealth XP. It spends run energy faster than running, less as your Stealth grows.": ["忍び足（走力の横のフードのボタン、または C）：攻撃的なモンスターのそばをそっと通り抜けます。ティックごとに気づかれる可能性があります（相手のレベル対あなたの隠密、距離、動いているか）。気づかれずに届かない所まで抜ければ隠密経験値。走るより走力を速く消費しますが、隠密が上がるほど減ります。", "살금살금(달리기 기력 옆 두건 버튼, 또는 C): 공격적인 몬스터 옆을 조용히 지나갑니다. 매 틱마다 들킬 수 있습니다(상대 레벨 대 당신의 은신술, 거리, 움직이는지 여부). 들키지 않고 사거리 밖으로 빠져나가면 은신술 경험치. 달리기보다 기력을 빨리 쓰지만, 은신술이 오를수록 덜 씁니다.", "潜行（奔跑体力旁的兜帽按钮，或 C 键）：轻手轻脚地走过有攻击性的怪物。每一刻它们都可能发现你（它们的等级对比你的潜行术、距离远近、你是否在移动）。不被发现地溜出范围可获得潜行术经验。它比奔跑更耗体力，潜行术越高消耗越少。", "潛行（奔跑體力旁的兜帽按鈕，或 C 鍵）：輕手輕腳地走過有攻擊性的怪物。每一刻牠們都可能發現你（牠們的等級對比你的潛行術、距離遠近、你是否在移動）。不被發現地溜出範圍可獲得潛行術經驗。它比奔跑更耗體力，潛行術越高消耗越少。", "Lén lút (nút mũ trùm cạnh năng lượng chạy, hoặc C): bước nhẹ qua những quái vật hung hăng. Mỗi nhịp chúng có thể phát hiện bạn (cấp của chúng so với Ẩn thân của bạn, khoảng cách, bạn có đang di chuyển không). Lẻn ra ngoài tầm mà không bị thấy để nhận XP Ẩn thân. Nó tốn năng lượng chạy nhanh hơn chạy, ít hơn khi Ẩn thân tăng.", "Mengendap (tombol tudung di samping energi lari, atau C): berjalan pelan melewati monster agresif. Setiap tik mereka bisa menyadarimu (level mereka melawan Silumanmu, seberapa dekat, apakah kamu bergerak). Lolos dari jangkauan tanpa terlihat untuk XP Siluman. Ini menghabiskan energi lari lebih cepat dari berlari, makin sedikit seiring Silumanmu tumbuh.", "ย่อง (ปุ่มฮู้ดข้างพลังวิ่ง หรือ C): เดินเบาๆ ผ่านมอนสเตอร์ที่ก้าวร้าว ทุกจังหวะพวกมันอาจสังเกตเห็นคุณ (เลเวลของมันเทียบกับลอบเร้นของคุณ ระยะห่าง และคุณขยับอยู่หรือไม่) หลุดพ้นระยะโดยไม่ถูกเห็นจะได้ XP ลอบเร้น ใช้พลังวิ่งเร็วกว่าการวิ่ง และน้อยลงเมื่อลอบเร้นสูงขึ้น", "Sinsice yürü (koşu enerjinin yanındaki kapüşonlu düğme ya da C): saldırgan canavarların yanından usulca geç. Her tikte seni fark edebilirler (onların seviyesine karşı senin Gizliliğin, ne kadar yakın olduğun, hareket edip etmediğin). Görülmeden menzilden çık, Gizlilik XP'si kazan. Koşmaktan daha hızlı koşu enerjisi harcar, Gizliliğin arttıkça daha az.", "Sigilo (el botón de la capucha junto a la energía de carrera, o C): pasa con cuidado junto a monstruos agresivos. Cada tic pueden notarte (su nivel contra tu Sigilo, lo cerca que estés y si te mueves). Escabúllete fuera de su alcance sin ser visto para ganar XP de Sigilo. Gasta energía de carrera más rápido que correr, y menos a medida que crece tu Sigilo.", "Esgueirar (o botão de capuz ao lado da energia de corrida, ou C): passe de mansinho por monstros agressivos. A cada tique eles podem notar você (o nível deles contra sua Furtividade, a distância, se você está se movendo). Escape do alcance sem ser visto para ganhar XP de Furtividade. Gasta energia de corrida mais rápido que correr, menos conforme sua Furtividade cresce.", "Красться (кнопка с капюшоном у энергии бега или C): тихо проходите мимо агрессивных монстров. Каждый тик они могут вас заметить (их уровень против вашей Скрытности, расстояние, двигаетесь ли вы). Ускользните из их досягаемости незамеченным — и получите опыт Скрытности. Тратит энергию бега быстрее бега, но меньше по мере роста Скрытности.", "Скрадатися (кнопка з каптуром біля енергії бігу або C): тихо проходьте повз агресивних монстрів. Щотіку вони можуть вас помітити (їхній рівень проти вашої Скритності, відстань, чи рухаєтеся ви). Вислизніть із досяжності непоміченим — і отримаєте досвід Скритності. Витрачає енергію бігу швидше за біг, але менше з ростом Скритності."],
  "Get spotted and the monster lunges at once: you take a hit, the sneak ends and the fight is on.": ["見つかるとモンスターはすぐさま飛びかかります：一撃を受け、忍び足は終わり、戦闘開始です。", "들키면 몬스터가 즉시 덤벼듭니다: 한 대 맞고, 살금살금이 끝나며, 싸움이 시작됩니다.", "一旦被发现，怪物会立刻扑来：你挨一下，潜行结束，战斗开始。", "一旦被發現，怪物會立刻撲來：你挨一下，潛行結束，戰鬥開始。", "Bị phát hiện thì quái vật lao tới ngay: bạn trúng một đòn, lén lút kết thúc và trận đánh bắt đầu.", "Ketahuan, monster langsung menerjang: kamu kena satu pukulan, mengendap berakhir, dan pertarungan dimulai.", "ถ้าถูกเห็น มอนสเตอร์จะพุ่งเข้าใส่ทันที: คุณโดนหนึ่งที การย่องจบลง และเริ่มต่อสู้", "Fark edilirsen canavar hemen saldırır: bir darbe yersin, sinsilik biter ve dövüş başlar.", "Si te ven, el monstruo se abalanza al instante: recibes un golpe, se acaba el sigilo y empieza la pelea.", "Se for visto, o monstro avança na hora: você leva um golpe, o esgueirar acaba e a luta começa.", "Если вас заметят, монстр сразу бросается: вы получаете удар, скрытное движение прерывается, и начинается бой.", "Якщо вас помітять, монстр одразу кидається: ви отримуєте удар, скрадання переривається, і починається бій."],
  "Sneak attacks: strike a monster that hasn't noticed you and your first blow lands harder and truer.": ["不意打ち：気づいていないモンスターを攻撃すると、最初の一撃がより強く、より正確に当たります。", "기습 공격: 당신을 눈치 못 챈 몬스터를 치면 첫 공격이 더 세고 정확하게 들어갑니다.", "偷袭：攻击尚未发现你的怪物，第一击会更重更准。", "偷襲：攻擊尚未發現你的怪物，第一擊會更重更準。", "Tấn công lén: đánh quái vật chưa phát hiện bạn thì đòn đầu tiên mạnh hơn và chính xác hơn.", "Serangan diam-diam: serang monster yang belum menyadarimu dan pukulan pertamamu lebih keras dan tepat.", "ลอบโจมตี: ตีมอนสเตอร์ที่ยังไม่เห็นคุณ แล้วการโจมตีครั้งแรกจะแรงและแม่นกว่า", "Sinsi saldırılar: seni fark etmemiş bir canavara vur, ilk darbe daha sert ve isabetli olur.", "Ataques furtivos: golpea a un monstruo que no te ha visto y tu primer golpe pega más fuerte y más certero.", "Ataques furtivos: acerte um monstro que não notou você e seu primeiro golpe sai mais forte e certeiro.", "Удар исподтишка: атакуйте монстра, который вас не заметил, и первый удар выйдет сильнее и точнее.", "Удар зненацька: атакуйте монстра, який вас не помітив, і перший удар буде сильнішим і точнішим."],
  "Light feet: from Stealth 50 aggressive monsters notice you from 3 tiles instead of 4, and from 80, only 2.": ["軽い足取り：隠密50から攻撃的なモンスターに気づかれる距離が4マスから3マスに、80からは2マスだけに。", "가벼운 발걸음: 은신술 50부터 공격적인 몬스터가 4칸 대신 3칸에서, 80부터는 2칸에서만 알아챕니다.", "轻盈步伐：潜行术 50 起，有攻击性的怪物发现你的距离从 4 格降为 3 格，80 起只有 2 格。", "輕盈步伐：潛行術 50 起，有攻擊性的怪物發現你的距離從 4 格降為 3 格，80 起只有 2 格。", "Bước chân nhẹ: từ Ẩn thân 50, quái vật hung hăng phát hiện bạn từ 3 ô thay vì 4, và từ 80 chỉ còn 2.", "Langkah ringan: dari Siluman 50 monster agresif menyadarimu dari 3 petak alih-alih 4, dan dari 80, hanya 2.", "เท้าเบา: ตั้งแต่ลอบเร้น 50 มอนสเตอร์ก้าวร้าวเห็นคุณจาก 3 ช่องแทน 4 และตั้งแต่ 80 แค่ 2", "Hafif ayaklar: Gizlilik 50'den itibaren saldırgan canavarlar seni 4 yerine 3 kareden, 80'den itibaren yalnızca 2 kareden fark eder.", "Pies ligeros: desde Sigilo 50 los monstruos agresivos te notan a 3 casillas en vez de 4, y desde 80, solo a 2.", "Pés leves: a partir de Furtividade 50 os monstros agressivos notam você a 3 blocos em vez de 4, e a partir de 80, só a 2.", "Лёгкая поступь: с Скрытности 50 агрессивные монстры замечают вас с 3 клеток вместо 4, а с 80 — только с 2.", "Легка хода: зі Скритності 50 агресивні монстри помічають вас із 3 клітинок замість 4, а з 80 — лише з 2."],
  "The Veilweave hood: found very rarely in the shadows while slipping past monsters of level 38 and up (Stealth 60). Wear it from 70 and stand still for five seconds, and you fade almost to nothing; aggressive monsters look straight through you. Other players see you fade too.": ["ヴェール織りの頭巾：レベル38以上のモンスターのそばをすり抜けるとき、ごくまれに影の中で見つかります（隠密60）。70からかぶって5秒じっとしていると、ほとんど消えるほど薄くなり、攻撃的なモンスターはあなたを素通りして見ます。ほかのプレイヤーにも薄れていく姿が見えます。", "베일직 두건: 레벨 38 이상 몬스터 옆을 빠져나갈 때 그림자 속에서 아주 드물게 발견됩니다(은신술 60). 70부터 쓰고 5초간 가만히 있으면 거의 사라질 만큼 희미해지고, 공격적인 몬스터가 당신을 꿰뚫어 봅니다. 다른 플레이어에게도 희미해지는 모습이 보입니다.", "纱织兜帽：在溜过 38 级以上怪物时，极少会在阴影中找到（潜行术 60）。70 级起戴上并静止五秒，你会淡得几乎消失；有攻击性的怪物会对你视而不见。其他玩家也能看到你渐渐淡去。", "紗織兜帽：在溜過 38 級以上怪物時，極少會在陰影中找到（潛行術 60）。70 級起戴上並靜止五秒，你會淡得幾乎消失；有攻擊性的怪物會對你視而不見。其他玩家也能看到你漸漸淡去。", "Mũ trùm dệt màn: rất hiếm khi tìm thấy trong bóng tối khi lẻn qua quái vật cấp 38 trở lên (Ẩn thân 60). Đội nó từ 70 và đứng yên năm giây, bạn mờ đi gần như biến mất; quái vật hung hăng nhìn xuyên qua bạn. Người chơi khác cũng thấy bạn mờ đi.", "Tudung tenun cadar: sangat jarang ditemukan dalam bayangan saat melewati monster level 38 ke atas (Siluman 60). Pakai dari 70 dan diam selama lima detik, kamu memudar hampir tak terlihat; monster agresif memandang tembus dirimu. Pemain lain juga melihatmu memudar.", "ผ้าคลุมหัวทอม่าน: หาได้น้อยมากในเงามืดขณะลอบผ่านมอนสเตอร์เลเวล 38 ขึ้นไป (ลอบเร้น 60) สวมได้ตั้งแต่ 70 และยืนนิ่งห้าวินาที คุณจะจางจนแทบหายไป มอนสเตอร์ก้าวร้าวมองทะลุตัวคุณ ผู้เล่นอื่นก็เห็นคุณจางไปด้วย", "Peçe dokuma başlık: 38 ve üstü seviyedeki canavarların yanından sıyrılırken gölgelerde çok nadiren bulunur (Gizlilik 60). 70'ten itibaren tak ve beş saniye kıpırdamadan dur, neredeyse hiçliğe solarsın; saldırgan canavarlar içinden geçip bakar. Diğer oyuncular da solduğunu görür.", "La Capucha de tejido velo: se encuentra muy de vez en cuando en las sombras al escabullirte de monstruos de nivel 38 o más (Sigilo 60). Póntela desde 70 y quédate quieto cinco segundos, y te desvanecerás casi del todo; los monstruos agresivos miran a través de ti. Los demás jugadores también te ven desvanecerte.", "O Capuz de trama-véu: achado muito raramente nas sombras ao passar despercebido por monstros de nível 38 ou mais (Furtividade 60). Use a partir de 70 e fique parado por cinco segundos, e você some quase por completo; monstros agressivos olham através de você. Outros jogadores também veem você sumir.", "Капюшон из вуалевой ткани: очень редко находится в тени, когда вы проскальзываете мимо монстров 38-го уровня и выше (Скрытность 60). Наденьте его с 70, постойте неподвижно пять секунд — и вы почти растворитесь; агрессивные монстры смотрят сквозь вас. Другие игроки тоже видят, как вы исчезаете.", "Каптур з вуалевої тканини: дуже рідко знаходиться в тіні, коли ви прослизаєте повз монстрів 38-го рівня й вище (Скритність 60). Надягніть його з 70, постійте нерухомо п'ять секунд — і ви майже розчинитеся; агресивні монстри дивляться крізь вас. Інші гравці теж бачать, як ви зникаєте."],
  "Two new achievements: Ghost in the grass and Now you see me.": ["新しい実績が2つ：「草むらの幽霊」と「見えたら最後」。", "새 업적 둘: '풀숲의 유령'과 '보였다 안 보였다'.", "两项新成就：「草中幽影」和「看得见我吗」。", "兩項新成就：「草中幽影」和「看得見我嗎」。", "Hai thành tựu mới: Bóng ma trong cỏ và Giờ thì thấy tôi rồi.", "Dua pencapaian baru: Hantu di rerumputan dan Kini kau melihatku.", "ความสำเร็จใหม่สองรายการ: ผีในพงหญ้า และ เห็นข้าแล้วสินะ", "İki yeni başarım: Çimenlerdeki hayalet ve Şimdi görüyorsun.", "Dos logros nuevos: Fantasma en la hierba y Ahora me ves.", "Duas conquistas novas: Fantasma na grama e Agora você me vê.", "Два новых достижения: «Призрак в траве» и «Видишь меня?».", "Два нові досягнення: «Привид у траві» і «Бачиш мене?»."],
  "Every room in the Realm is lamplit: hanging lanterns in the houses and shops, iron chandeliers in the castle's halls, on every storey. Windows glow warm at night.": ["レルムのすべての部屋にランプが灯ります：家や店には吊りランタン、城の広間には鉄のシャンデリアが各階に。夜には窓が暖かく輝きます。", "렐름의 모든 방에 등불이 켜집니다: 집과 가게엔 걸이 랜턴, 성의 홀엔 층마다 쇠 샹들리에. 밤엔 창문이 따뜻하게 빛납니다.", "王国中的每个房间都点起了灯：民居和商店里挂着灯笼，城堡各层大厅里挂着铁吊灯。夜里窗户透出温暖的光。", "王國中的每個房間都點起了燈：民居和商店裡掛著燈籠，城堡各層大廳裡掛著鐵吊燈。夜裡窗戶透出溫暖的光。", "Mọi căn phòng trong Vương quốc đều thắp đèn: đèn lồng treo trong nhà và cửa hàng, đèn chùm sắt trong các sảnh lâu đài, ở mọi tầng. Cửa sổ sáng ấm vào ban đêm.", "Setiap ruangan di Realm diterangi lampu: lentera gantung di rumah dan toko, lampu gantung besi di aula kastel, di setiap lantai. Jendela bersinar hangat di malam hari.", "ทุกห้องในอาณาจักรมีตะเกียง: โคมแขวนในบ้านและร้านค้า โคมระย้าเหล็กในห้องโถงปราสาททุกชั้น หน้าต่างเรืองแสงอบอุ่นยามค่ำ", "Diyar'daki her oda lambalı: evlerde ve dükkânlarda asılı fenerler, kalenin salonlarında her katta demir avizeler. Pencereler gece sıcak sıcak parlıyor.", "Todas las salas del Reino están iluminadas: faroles colgantes en las casas y tiendas, lámparas de hierro en los salones del castillo, en todas las plantas. Las ventanas brillan cálidas de noche.", "Todas as salas do Reino são iluminadas: lanternas penduradas nas casas e lojas, lustres de ferro nos salões do castelo, em todos os andares. As janelas brilham quentes à noite.", "Во всех комнатах Королевства горит свет: подвесные фонари в домах и лавках, железные люстры в залах замка на каждом этаже. Ночью окна тепло светятся.", "У всіх кімнатах Королівства горить світло: підвісні ліхтарі в будинках і крамницях, залізні люстри в залах замку на кожному поверсі. Уночі вікна тепло світяться."],
  "Mastery capes stand out as capes of accomplishment: a yoke across the shoulders in the skill's second colour, a band above the hem, the skill's emblem on the back in a roundel, and gold edges on trimmed capes. The Grandmaster's carries a gold star.": ["マスターマントは偉業のマントとして目立つように：肩にスキルの第二色のヨーク、裾の上に帯、背中の円章にスキルの紋章、縁取りマントには金の縁。極のマントには金の星。", "마스터리 망토가 업적의 망토로 돋보입니다: 어깨엔 스킬의 두 번째 색 요크, 밑단 위엔 띠, 등엔 원형 문장 속 스킬 엠블럼, 장식 망토엔 금 테두리. 그랜드마스터의 망토엔 금별이 있습니다.", "精通披风作为成就披风格外醒目：肩部有技能第二色的育克，下摆上方有一道饰带，背后圆章中有技能徽记，镶边披风带金边。宗师披风还有一颗金星。", "精通披風作為成就披風格外醒目：肩部有技能第二色的育克，下襬上方有一道飾帶，背後圓章中有技能徽記，鑲邊披風帶金邊。宗師披風還有一顆金星。", "Áo choàng tinh thông nổi bật như áo choàng thành tựu: miếng đệm vai màu thứ hai của kỹ năng, một dải trên gấu, biểu tượng kỹ năng trong huy hiệu tròn sau lưng, và viền vàng trên áo choàng viền. Áo của Đại sư mang một ngôi sao vàng.", "Jubah penguasaan menonjol sebagai jubah prestasi: kuk di bahu dalam warna kedua keahlian, pita di atas kelim, lambang keahlian di punggung dalam medali bundar, dan tepi emas pada jubah berhias. Jubah Grandmaster membawa bintang emas.", "ผ้าคลุมความเชี่ยวชาญโดดเด่นเป็นผ้าคลุมแห่งความสำเร็จ: แผงบ่าสีที่สองของทักษะ แถบเหนือชายผ้า ตราทักษะในวงกลมที่หลัง และขอบทองบนผ้าคลุมแบบขลิบ ของยอดปรมาจารย์มีดาวทอง", "Ustalık pelerinleri başarı pelerinleri olarak göze çarpıyor: omuzlarda becerinin ikinci renginde bir boyunduruk, eteğin üstünde bir şerit, sırtta bir madalyon içinde becerinin amblemi ve süslü pelerinlerde altın kenarlar. Büyük ustanınkinde altın bir yıldız var.", "Las capas de maestría destacan como capas de logro: un canesú sobre los hombros en el segundo color de la habilidad, una franja sobre el dobladillo, el emblema de la habilidad a la espalda en un medallón y bordes dorados en las capas ribeteadas. La del Gran maestro lleva una estrella dorada.", "As capas de maestria se destacam como capas de conquista: uma pala nos ombros na segunda cor da habilidade, uma faixa acima da barra, o emblema da habilidade nas costas num medalhão e bordas douradas nas capas debruadas. A do Grão-mestre traz uma estrela dourada.", "Плащи мастерства выделяются как плащи достижений: кокетка на плечах во втором цвете навыка, полоса над подолом, эмблема навыка в медальоне на спине и золотая кайма на отделанных плащах. У плаща Гроссмейстера — золотая звезда.", "Плащі майстерності виділяються як плащі досягнень: кокетка на плечах у другому кольорі навички, смуга над подолом, емблема навички в медальйоні на спині й золота облямівка на оздоблених плащах. На плащі Гросмейстера — золота зірка."],
  "Hollow Square's fountain is rebuilt: a wide eight-sided stone basin of pixel water with wishing coins, a column and a bowl spilling over its lip, and a jet on top. It glows softly at night.": ["ホロウ広場の噴水を作り直しました：願いのコインが沈むピクセルの水をたたえた広い八角形の石の水盤、柱と縁からあふれる鉢、そして頂上の噴き上げ。夜にはやわらかく光ります。", "할로우 광장 분수가 새로 지어졌습니다: 소원 동전이 담긴 픽셀 물의 넓은 팔각 돌 수반, 기둥과 가장자리로 넘쳐흐르는 그릇, 그리고 꼭대기의 물줄기. 밤엔 은은하게 빛납니다.", "空谷广场的喷泉重建了：宽大的八角石池盛着像素水和许愿币，一根石柱托着溢水的石碗，顶上还有一道喷泉。夜里会发出柔和的光。", "空谷廣場的噴泉重建了：寬大的八角石池盛著像素水和許願幣，一根石柱托著溢水的石碗，頂上還有一道噴泉。夜裡會發出柔和的光。", "Đài phun nước Quảng trường Hollow được xây lại: một bể đá tám cạnh rộng với nước pixel và đồng xu ước nguyện, một cột và một chiếc bát tràn nước qua miệng, cùng một tia nước trên đỉnh. Ban đêm nó phát sáng dịu.", "Air mancur Alun-alun Hollow dibangun ulang: kolam batu bersegi delapan yang lebar berisi air piksel dengan koin harapan, tiang dan mangkuk yang meluap, dan semburan di puncaknya. Ia bersinar lembut di malam hari.", "น้ำพุจัตุรัสฮอลโลว์สร้างใหม่: อ่างหินแปดเหลี่ยมกว้างมีน้ำพิกเซลกับเหรียญอธิษฐาน เสาและชามที่น้ำล้นขอบ และน้ำพุ่งบนยอด เรืองแสงนุ่มๆ ยามค่ำ", "Hollow Meydanı'nın çeşmesi yeniden yapıldı: dilek paralarıyla dolu piksel sulu geniş, sekiz kenarlı bir taş havuz, bir sütun, kenarından taşan bir kâse ve tepede bir fıskiye. Gece hafifçe parlıyor.", "La fuente de la Plaza Hollow se ha reconstruido: un amplio pilón de piedra de ocho lados con agua pixelada y monedas de deseos, una columna y una taza que rebosa, y un surtidor en lo alto. De noche brilla suavemente.", "A fonte da Praça Hollow foi reconstruída: uma bacia de pedra larga de oito lados com água de pixel e moedas de desejo, uma coluna e uma tigela transbordando pela borda e um jato no topo. Ela brilha suave à noite.", "Фонтан на Площади Холлоу отстроен заново: широкая восьмигранная каменная чаша с пиксельной водой и монетками на желание, колонна и чаша, переливающаяся через край, и струя сверху. Ночью он мягко светится.", "Фонтан на Площі Голлоу відбудовано: широка восьмигранна кам'яна чаша з піксельною водою й монетками на бажання, колона й чаша, що переливається через край, і струмінь угорі. Уночі він м'яко світиться."],
  "Fixed: shared fights and dropped items in the Greyhorn Highlands (the far east) now work with other players.": ["修正：グレイホーン高地（東の果て）での共闘と落としたアイテムが、ほかのプレイヤーとも正しく機能するように。", "수정: 그레이혼 고원(먼 동쪽)에서 함께 싸우기와 떨어뜨린 아이템이 이제 다른 플레이어와도 작동합니다.", "修复：灰角高地（远东）的共同战斗和掉落物品现在能与其他玩家正常互通。", "修復：灰角高地（遠東）的共同戰鬥和掉落物品現在能與其他玩家正常互通。", "Đã sửa: đánh chung và vật phẩm rơi ở Cao nguyên Greyhorn (viễn đông) giờ hoạt động với người chơi khác.", "Diperbaiki: pertarungan bersama dan barang jatuh di Dataran Tinggi Greyhorn (ujung timur) kini berfungsi dengan pemain lain.", "แก้ไข: การต่อสู้ร่วมกันและไอเท็มที่ทิ้งในที่ราบสูงเกรย์ฮอร์น (ตะวันออกสุด) ตอนนี้ใช้ได้กับผู้เล่นอื่น", "Düzeltildi: Greyhorn Yaylaları'nda (uzak doğu) ortak dövüşler ve düşürülen eşyalar artık diğer oyuncularla çalışıyor.", "Corregido: las peleas compartidas y los objetos soltados en las Tierras Altas de Greyhorn (el lejano este) ya funcionan con otros jugadores.", "Corrigido: lutas compartilhadas e itens largados nas Terras Altas de Greyhorn (o extremo leste) agora funcionam com outros jogadores.", "Исправлено: совместные бои и брошенные предметы на Грейхорнском нагорье (дальний восток) теперь работают с другими игроками.", "Виправлено: спільні бої та кинуті предмети на Грейгорнському нагір'ї (далекий схід) тепер працюють з іншими гравцями."],
  "Bank tabs fixed, and save codes that stay saved": ["銀行タブの修正と、消えないセーブコード", "은행 탭 수정, 그리고 저장이 유지되는 저장 코드", "修复银行标签，存档码不再丢失", "修復銀行分頁，存檔碼不再遺失", "Sửa thẻ ngân hàng, và mã lưu luôn được lưu", "Tab bank diperbaiki, dan kode simpanan yang tetap tersimpan", "แก้แท็บธนาคาร และรหัสบันทึกที่บันทึกอยู่เสมอ", "Banka sekmeleri düzeltildi ve kaydedilmiş kalan kayıt kodları", "Pestañas del banco arregladas y códigos de guardado que se quedan guardados", "Abas do banco corrigidas e códigos de salvamento que continuam salvos", "Исправлены вкладки банка, а коды сохранения не теряются", "Виправлено вкладки банку, а коди збереження не губляться"],
  "Bank tabs no longer squash the bank: with several tabs the All items view lists each tab under its own heading and scrolls, and the shop's stock does the same.": ["銀行タブで銀行が窮屈にならないように：タブが複数あると「すべてのアイテム」画面は各タブを見出しごとに並べてスクロールでき、店の在庫も同様です。", "은행 탭이 더 이상 은행을 짓누르지 않습니다: 탭이 여럿이면 '모든 아이템' 보기가 탭마다 제목 아래 나열하고 스크롤되며, 상점 재고도 마찬가지입니다.", "银行标签不再挤压银行界面：有多个标签时，「全部物品」视图会按各自标题分组列出每个标签并可滚动，商店库存也一样。", "銀行分頁不再擠壓銀行介面：有多個分頁時，「全部物品」檢視會按各自標題分組列出每個分頁並可捲動，商店庫存也一樣。", "Thẻ ngân hàng không còn làm chật ngân hàng: khi có nhiều thẻ, chế độ Tất cả vật phẩm liệt kê từng thẻ dưới tiêu đề riêng và cuộn được, hàng của cửa hàng cũng vậy.", "Tab bank tak lagi menjepit bank: dengan beberapa tab, tampilan Semua barang mencantumkan tiap tab di bawah judulnya sendiri dan bisa digulir, begitu juga stok toko.", "แท็บธนาคารไม่บีบธนาคารอีก: เมื่อมีหลายแท็บ มุมมองไอเท็มทั้งหมดจะแสดงแต่ละแท็บใต้หัวข้อของตัวเองและเลื่อนได้ สต็อกของร้านก็เช่นกัน", "Banka sekmeleri artık bankayı sıkıştırmıyor: birkaç sekme varken Tüm eşyalar görünümü her sekmeyi kendi başlığı altında listeliyor ve kayıyor; dükkânın stoku da aynı.", "Las pestañas ya no aplastan el banco: con varias pestañas, la vista de Todos los objetos muestra cada una bajo su propio encabezado y se desplaza, y el surtido de la tienda hace lo mismo.", "As abas não espremem mais o banco: com várias abas, a vista Todos os itens lista cada aba sob seu próprio título e rola, e o estoque da loja faz o mesmo.", "Вкладки больше не сжимают банк: при нескольких вкладках вид «Все предметы» показывает каждую под своим заголовком и прокручивается, и ассортимент лавки — тоже.", "Вкладки більше не стискають банк: за кількох вкладок вид «Усі предмети» показує кожну під власним заголовком і прокручується, і асортимент крамниці — теж."],
  "Restoring a save code saves it at once. Before, a second tab or window with the game open could quietly overwrite the restored adventure with its own.": ["セーブコードを復元するとすぐに保存されます。以前は、ゲームを開いた別のタブやウィンドウが、復元した冒険を自分のデータでこっそり上書きすることがありました。", "저장 코드를 복원하면 즉시 저장됩니다. 전에는 게임이 열린 다른 탭이나 창이 복원한 모험을 자기 것으로 조용히 덮어쓸 수 있었습니다.", "恢复存档码会立即保存。以前，打开游戏的第二个标签页或窗口可能会悄悄用自己的数据覆盖已恢复的冒险。", "恢復存檔碼會立即保存。以前，開啟遊戲的第二個分頁或視窗可能會悄悄用自己的資料覆蓋已恢復的冒險。", "Khôi phục mã lưu sẽ lưu ngay. Trước đây, một tab hoặc cửa sổ thứ hai đang mở game có thể âm thầm ghi đè cuộc phiêu lưu vừa khôi phục bằng dữ liệu của nó.", "Memulihkan kode simpanan langsung menyimpannya. Sebelumnya, tab atau jendela kedua yang membuka game bisa diam-diam menimpa petualangan yang dipulihkan dengan miliknya.", "การกู้คืนรหัสบันทึกจะบันทึกทันที ก่อนหน้านี้ แท็บหรือหน้าต่างที่สองที่เปิดเกมอยู่อาจเขียนทับการผจญภัยที่กู้คืนด้วยข้อมูลของมันโดยไม่รู้ตัว", "Bir kayıt kodunu geri yüklemek onu hemen kaydeder. Önceden oyunun açık olduğu ikinci bir sekme ya da pencere, geri yüklenen macerayı sessizce kendi verisiyle üzerine yazabiliyordu.", "Restaurar un código de guardado lo guarda al instante. Antes, una segunda pestaña o ventana con el juego abierto podía sobrescribir sin avisar la aventura restaurada con la suya.", "Restaurar um código de salvamento salva na hora. Antes, uma segunda aba ou janela com o jogo aberto podia sobrescrever em silêncio a aventura restaurada com a dela.", "Восстановленный код сохранения сохраняется сразу. Раньше вторая вкладка или окно с игрой могли незаметно перезаписать восстановленное приключение своим.", "Відновлений код збереження зберігається одразу. Раніше друга вкладка чи вікно з грою могли непомітно перезаписати відновлену пригоду своєю."],
  "One tab saves at a time: when you open the Realm in a newer tab, the older one stops saving and tells you so (reload it to continue there).": ["保存するのは一度に1つのタブだけ：新しいタブでレルムを開くと、古いタブは保存をやめてそう知らせます（そちらで続けるには再読み込み）。", "한 번에 한 탭만 저장합니다: 새 탭에서 렐름을 열면 이전 탭은 저장을 멈추고 알려 줍니다(거기서 계속하려면 새로고침).", "一次只有一个标签页保存：在新标签页中打开王国时，旧标签页会停止保存并提示你（重新加载即可在那边继续）。", "一次只有一個分頁保存：在新分頁中開啟王國時，舊分頁會停止保存並提示你（重新載入即可在那邊繼續）。", "Mỗi lúc chỉ một tab lưu: khi bạn mở Vương quốc ở tab mới hơn, tab cũ ngừng lưu và báo cho bạn (tải lại để tiếp tục ở đó).", "Satu tab menyimpan dalam satu waktu: saat membuka Realm di tab yang lebih baru, tab lama berhenti menyimpan dan memberitahumu (muat ulang untuk melanjutkan di sana).", "บันทึกได้ทีละแท็บ: เมื่อเปิดอาณาจักรในแท็บใหม่ แท็บเก่าจะหยุดบันทึกและแจ้งให้ทราบ (โหลดใหม่เพื่อเล่นต่อที่นั่น)", "Aynı anda bir sekme kaydeder: Diyar'ı daha yeni bir sekmede açtığında eskisi kaydetmeyi bırakır ve bunu söyler (orada devam etmek için yeniden yükle).", "Solo guarda una pestaña a la vez: al abrir el Reino en una pestaña más nueva, la antigua deja de guardar y te lo dice (recárgala para seguir allí).", "Só uma aba salva por vez: ao abrir o Reino numa aba mais nova, a antiga para de salvar e avisa você (recarregue-a para continuar lá).", "Сохраняет только одна вкладка: когда вы открываете Королевство в новой вкладке, старая перестаёт сохранять и сообщает об этом (перезагрузите её, чтобы продолжить там).", "Зберігає лише одна вкладка: коли ви відкриваєте Королівство в новій вкладці, стара перестає зберігати й повідомляє про це (перезавантажте її, щоб продовжити там)."],
  "Settings says plainly when saves aren't connected, and the page keeps trying to connect them for about a minute instead of ten seconds.": ["セーブが接続されていないときは設定画面にはっきり表示され、ページは10秒ではなく約1分間接続を試み続けます。", "저장이 연결되지 않았으면 설정에 분명히 표시되고, 페이지는 10초가 아니라 약 1분 동안 연결을 계속 시도합니다.", "存档未连接时，设置中会明确说明，页面会持续尝试连接约一分钟，而不是十秒。", "存檔未連線時，設定中會明確說明，頁面會持續嘗試連線約一分鐘，而不是十秒。", "Cài đặt nói rõ khi bản lưu chưa được kết nối, và trang tiếp tục thử kết nối khoảng một phút thay vì mười giây.", "Pengaturan menyatakan dengan jelas bila simpanan tak terhubung, dan halaman terus mencoba menghubungkannya sekitar semenit, bukan sepuluh detik.", "การตั้งค่าบอกชัดเจนเมื่อบันทึกไม่ได้เชื่อมต่อ และหน้าเว็บจะพยายามเชื่อมต่อต่อไปประมาณหนึ่งนาทีแทนสิบวินาที", "Ayarlar, kayıtlar bağlı olmadığında bunu açıkça söylüyor ve sayfa on saniye yerine yaklaşık bir dakika bağlanmayı denemeye devam ediyor.", "Los ajustes dicen claramente cuando el guardado no está conectado, y la página sigue intentando conectarlo durante un minuto en vez de diez segundos.", "As configurações dizem claramente quando os salvamentos não estão conectados, e a página continua tentando conectar por cerca de um minuto em vez de dez segundos.", "Настройки прямо сообщают, когда сохранения не подключены, а страница пытается подключиться около минуты вместо десяти секунд.", "Налаштування прямо повідомляють, коли збереження не під'єднані, а сторінка намагається під'єднатися близько хвилини замість десяти секунд."],
  "Low graphics that look like High, and a roomier town": ["高画質のように見える低画質と、ゆったりした町", "높음처럼 보이는 낮음 그래픽, 그리고 더 넉넉한 마을", "看起来像高画质的低画质，以及更宽敞的小镇", "看起來像高畫質的低畫質，以及更寬敞的小鎮", "Đồ họa Thấp trông như Cao, và thị trấn rộng rãi hơn", "Grafis Rendah yang tampak seperti Tinggi, dan kota yang lebih lega", "กราฟิกต่ำที่ดูเหมือนสูง และเมืองที่กว้างขวางขึ้น", "Yüksek gibi görünen düşük grafikler ve daha ferah bir kasaba", "Gráficos Bajos que parecen Altos y un pueblo más amplio", "Gráficos Baixos que parecem Altos e uma cidade mais espaçosa", "Низкая графика, похожая на высокую, и просторный город", "Низька графіка, схожа на високу, і просторіше місто"],
  "Low graphics now use High's textures and lighting: the same ground, walls and roofs, the same daylight, dusk and lamplight, and buildings still cast their shadows. Low leaves out the shadows of trees and Friends, the far haze and cloud shadows, and lays its light more coarsely, so it stays quick.": ["低画質でも高画質のテクスチャとライティングを使うように：同じ地面、壁、屋根、同じ日光、夕暮れ、ランプの明かり、建物の影もそのまま。低画質は木やフレンドの影、遠景のもや、雲の影を省き、光を粗く置くので軽快なままです。", "그래픽 낮음도 이제 높음의 텍스처와 조명을 씁니다: 같은 바닥, 벽, 지붕, 같은 햇빛, 해 질 녘, 등불, 건물 그림자도 그대로. 낮음은 나무와 프렌드의 그림자, 원경 아지랑이, 구름 그림자를 빼고 빛을 더 거칠게 깔아 빠르게 유지됩니다.", "低画质现在使用高画质的纹理和光照：同样的地面、墙壁和屋顶，同样的日光、黄昏和灯光，建筑依然投下阴影。低画质省去树木和伙伴的影子、远景雾霭和云影，光照也更粗略，因此依然流畅。", "低畫質現在使用高畫質的紋理和光照：同樣的地面、牆壁和屋頂，同樣的日光、黃昏和燈光，建築依然投下陰影。低畫質省去樹木和夥伴的影子、遠景霧靄和雲影，光照也更粗略，因此依然流暢。", "Đồ họa Thấp giờ dùng kết cấu và ánh sáng của Cao: cùng mặt đất, tường và mái, cùng ánh ngày, hoàng hôn và ánh đèn, và nhà cửa vẫn đổ bóng. Thấp bỏ bóng của cây và Bạn, sương xa và bóng mây, và trải ánh sáng thô hơn, nên vẫn nhanh.", "Grafis Rendah kini memakai tekstur dan pencahayaan Tinggi: tanah, dinding, dan atap yang sama, cahaya siang, senja, dan lampu yang sama, dan bangunan tetap membentuk bayangan. Rendah meniadakan bayangan pohon dan Sahabat, kabut jauh, dan bayangan awan, serta memasang cahaya lebih kasar, jadi tetap cepat.", "กราฟิกต่ำตอนนี้ใช้พื้นผิวและแสงของกราฟิกสูง: พื้น กำแพง และหลังคาเดียวกัน แสงกลางวัน ยามพลบ และแสงตะเกียงเดียวกัน และอาคารยังทอดเงา กราฟิกต่ำตัดเงาของต้นไม้และเพื่อน หมอกไกล และเงาเมฆ และวางแสงหยาบกว่า จึงยังเร็ว", "Düşük grafikler artık Yüksek'in dokularını ve aydınlatmasını kullanıyor: aynı zemin, duvarlar ve çatılar, aynı gün ışığı, alacakaranlık ve lamba ışığı, binalar hâlâ gölge düşürüyor. Düşük, ağaçların ve Dostların gölgelerini, uzak pusu ve bulut gölgelerini atlıyor ve ışığı daha kaba yerleştiriyor, böylece hızlı kalıyor.", "Los gráficos Bajos usan ahora las texturas e iluminación de Alto: el mismo suelo, muros y tejados, la misma luz del día, atardecer y faroles, y los edificios siguen proyectando sombra. Bajo omite las sombras de árboles y Amigos, la bruma lejana y las sombras de nubes, y reparte la luz con menos detalle, así que sigue siendo rápido.", "Os gráficos Baixos agora usam as texturas e a iluminação do Alto: o mesmo chão, paredes e telhados, a mesma luz do dia, entardecer e lampiões, e os prédios ainda projetam sombras. O Baixo deixa de fora as sombras de árvores e Amigos, a névoa distante e as sombras de nuvens, e aplica a luz de forma mais grossa, então continua rápido.", "Низкая графика теперь использует текстуры и освещение высокой: та же земля, стены и крыши, тот же дневной свет, сумерки и свет фонарей, и здания по-прежнему отбрасывают тени. Низкая опускает тени деревьев и Друзей, дальнюю дымку и тени облаков и кладёт свет грубее, чтобы оставаться быстрой.", "Низька графіка тепер використовує текстури й освітлення високої: та сама земля, стіни й дахи, те саме денне світло, сутінки й світло ліхтарів, і будівлі досі відкидають тіні. Низька пропускає тіні дерев і Друзів, дальній серпанок і тіні хмар і кладе світло грубіше, щоб лишатися швидкою."],
  "Both settings draw faster: nothing off the screen is drawn, and the hidden sides of flat roofs and walls are skipped.": ["どちらの設定も描画が速くなりました：画面外は描かず、平らな屋根や壁の隠れた面は省きます。", "두 설정 모두 더 빨리 그립니다: 화면 밖은 그리지 않고, 평평한 지붕과 벽의 숨은 면은 건너뜁니다.", "两种设置都绘制得更快了：屏幕外的东西不再绘制，平屋顶和墙壁的隐藏面会被跳过。", "兩種設定都繪製得更快了：螢幕外的東西不再繪製，平屋頂和牆壁的隱藏面會被跳過。", "Cả hai thiết lập đều vẽ nhanh hơn: không vẽ gì ngoài màn hình, và bỏ qua các mặt khuất của mái bằng và tường.", "Kedua pengaturan menggambar lebih cepat: tak ada yang di luar layar digambar, dan sisi tersembunyi atap datar serta dinding dilewati.", "ทั้งสองแบบวาดเร็วขึ้น: ไม่วาดสิ่งที่อยู่นอกจอ และข้ามด้านที่ซ่อนของหลังคาแบนและกำแพง", "İki ayar da daha hızlı çiziyor: ekran dışındaki hiçbir şey çizilmiyor, düz çatıların ve duvarların gizli yüzleri atlanıyor.", "Ambos ajustes dibujan más rápido: no se dibuja nada fuera de pantalla y se omiten las caras ocultas de tejados planos y muros.", "As duas opções desenham mais rápido: nada fora da tela é desenhado, e os lados ocultos de telhados planos e paredes são pulados.", "Оба режима рисуют быстрее: за пределами экрана ничего не рисуется, а скрытые стороны плоских крыш и стен пропускаются.", "Обидва режими малюють швидше: за межами екрана нічого не малюється, а приховані боки пласких дахів і стін пропускаються."],
  "The Sleepy Friend inn has moved across the east bridge, on its own with a cobbled step up to its door, and the house behind Fletch & Feather has moved back so its door isn't a tile from the next wall.": ["Sleepy Friend の宿は東の橋を渡った先へ移り、石畳の段が扉まで続く一軒家に。フレッチ&フェザーの裏の家も奥へ下がり、扉が隣の壁から1マスの位置ではなくなりました。", "Sleepy Friend 여관이 동쪽 다리 건너로 옮겨 문까지 자갈 계단이 있는 독채가 되었고, 플레치 앤 페더 뒤의 집은 뒤로 물러나 문이 옆 벽에서 한 칸 거리가 아니게 되었습니다.", "Sleepy Friend 旅店搬到了东桥对面，独门独户，门前有一级鹅卵石台阶；箭羽铺后面的房子也往后挪了，门不再离隔壁墙只有一格。", "Sleepy Friend 旅店搬到了東橋對面，獨門獨戶，門前有一級鵝卵石台階；箭羽鋪後面的房子也往後挪了，門不再離隔壁牆只有一格。", "Quán trọ Sleepy Friend đã dời qua cầu phía đông, đứng riêng với bậc đá cuội lên cửa, và ngôi nhà sau Fletch & Feather lùi lại để cửa không còn cách bức tường kế bên một ô.", "Penginapan Sleepy Friend pindah ke seberang jembatan timur, berdiri sendiri dengan undakan berbatu ke pintunya, dan rumah di belakang Fletch & Feather mundur agar pintunya tak sejarak satu petak dari dinding sebelah.", "โรงเตี๊ยม Sleepy Friend ย้ายข้ามสะพานตะวันออก ตั้งอยู่เดี่ยวๆ พร้อมขั้นหินกรวดขึ้นประตู และบ้านหลังเฟล็ตช์แอนด์เฟเธอร์ถอยไปข้างหลังจนประตูไม่ห่างกำแพงถัดไปแค่หนึ่งช่อง", "Sleepy Friend hanı doğu köprüsünün karşısına, kapısına çıkan arnavut kaldırımlı bir basamakla tek başına taşındı; Fletch & Feather'ın arkasındaki ev de geri çekildi, kapısı artık yandaki duvardan bir kare uzakta değil.", "La posada Sleepy Friend se ha mudado al otro lado del puente este, sola y con un escalón empedrado hasta la puerta, y la casa detrás de Fletch & Feather se ha retirado para que su puerta no quede a una casilla del muro de al lado.", "A estalagem Sleepy Friend mudou para o outro lado da ponte leste, sozinha com um degrau de pedra até a porta, e a casa atrás da Fletch & Feather recuou para que a porta não fique a um bloco da parede vizinha.", "Трактир Sleepy Friend переехал за восточный мост и стоит отдельно с мощёной ступенькой к двери, а дом за «Стрелой и пером» отодвинут, чтобы его дверь не была в клетке от соседней стены.", "Корчма Sleepy Friend переїхала за східний міст і стоїть окремо з брукованою сходинкою до дверей, а дім за «Стрілою й пером» відсунуто, щоб його двері не були за клітинку від сусідньої стіни."],
  "Real clothes, boots and gauntlets, and armour that fits": ["本物の服、ブーツと籠手、そして体に合う鎧", "진짜 옷, 장화와 건틀릿, 그리고 꼭 맞는 갑옷", "真正的衣服、靴子与护手，以及合身的盔甲", "真正的衣服、靴子與護手，以及合身的盔甲", "Quần áo thật, ủng và găng giáp, và giáp vừa vặn", "Pakaian sungguhan, sepatu bot dan sarung tangan zirah, dan zirah yang pas", "เสื้อผ้าจริง รองเท้าบูตและถุงมือเกราะ และเกราะที่พอดีตัว", "Gerçek kıyafetler, botlar ve eldivenler ve tam oturan zırh", "Ropa de verdad, botas y guanteletes, y armaduras que encajan", "Roupas de verdade, botas e manoplas, e armaduras que servem", "Настоящая одежда, сапоги и латные перчатки, и доспехи по фигуре", "Справжній одяг, чоботи й латні рукавиці та обладунки по фігурі"],
  "Ribbon & Rye Clothiers, west of the south end of Market Street: shirts in eight colours, belted tunics, dresses that sweep the floor, trousers and skirts. They're for looks (no combat bonuses), and the townsfolk wear them too.": ["Market Street 南端の西にリボン&ライ洋品店：8色のシャツ、ベルト付きチュニック、床まで届くドレス、ズボンとスカート。見た目用（戦闘ボーナスなし）で、町の人々も着ています。", "Market Street 남쪽 끝 서쪽의 리본 앤 라이 옷가게: 여덟 색 셔츠, 허리띠 튜닉, 바닥을 쓰는 드레스, 바지와 치마. 외형용(전투 보너스 없음)이고, 마을 사람들도 입습니다.", "Market Street 南端西侧的丝带与黑麦服装店：八种颜色的衬衫、系带束腰外衣、拖地长裙、长裤和短裙。它们只为好看（没有战斗加成），镇上的居民也会穿。", "Market Street 南端西側的絲帶與黑麥服裝店：八種顏色的襯衫、繫帶束腰外衣、拖地長裙、長褲和短裙。它們只為好看（沒有戰鬥加成），鎮上的居民也會穿。", "Tiệm áo Ribbon & Rye, phía tây đầu nam Market Street: áo sơ mi tám màu, áo chẽn có thắt lưng, váy dài quét đất, quần dài và chân váy. Chúng để làm đẹp (không có thưởng chiến đấu), và dân thị trấn cũng mặc.", "Toko Pakaian Ribbon & Rye, di barat ujung selatan Market Street: kemeja dalam delapan warna, tunik bersabuk, gaun yang menyapu lantai, celana, dan rok. Untuk penampilan (tanpa bonus tempur), dan warga kota juga memakainya.", "ร้านเสื้อผ้าริบบอนแอนด์ไร ทางตะวันตกของปลายใต้ Market Street: เสื้อเชิ้ตแปดสี ทูนิกคาดเข็มขัด ชุดยาวลากพื้น กางเกง และกระโปรง ใส่เพื่อความสวยงาม (ไม่มีโบนัสการต่อสู้) และชาวเมืองก็ใส่ด้วย", "Market Street'in güney ucunun batısında Ribbon & Rye Giyim: sekiz renkte gömlekler, kemerli tunikler, yere değen elbiseler, pantolonlar ve etekler. Görünüş içindir (savaş bonusu yok) ve kasaba halkı da giyiyor.", "La Ropería Cinta y Centeno, al oeste del extremo sur de Market Street: camisas en ocho colores, túnicas con cinturón, vestidos que barren el suelo, pantalones y faldas. Son de adorno (sin bonificaciones de combate), y la gente del pueblo también los lleva.", "Roupas Fita & Centeio, a oeste do extremo sul da Market Street: camisas em oito cores, túnicas com cinto, vestidos que arrastam no chão, calças e saias. São só visuais (sem bônus de combate), e o povo da cidade também usa.", "Одежда «Лента и рожь», к западу от южного конца Market Street: рубашки восьми цветов, туники с поясом, платья в пол, брюки и юбки. Это для красоты (без боевых бонусов), и горожане тоже их носят.", "Одяг «Стрічка й жито», на захід від південного кінця Market Street: сорочки восьми кольорів, туніки з поясом, сукні в підлогу, штани й спідниці. Це для краси (без бойових бонусів), і городяни теж їх носять."],
  "Boots and gauntlets in every metal, smithed at the anvil (one bar each) and sold beside the helms in the armouries. Dawnplate has them too: boots from The Pilgrim's Road, gauntlets from The Restless Crypt.": ["全金属のブーツと籠手：金床で鍛え（各1本）、防具屋で兜と並んで売られています。Dawnplate にもあります：ブーツは「巡礼の道」、籠手は「眠らぬ地下墓所」から。", "모든 금속의 장화와 건틀릿: 모루에서 만들고(각 주괴 1개) 방어구점에서 투구 옆에 팝니다. Dawnplate에도 있습니다: 장화는 '순례자의 길', 건틀릿은 '잠들지 못하는 지하묘지'에서.", "各种金属的靴子和护手：在铁砧上锻造（各 1 块锭），在护甲铺里和头盔摆在一起出售。Dawnplate 也有：靴子来自「朝圣之路」，护手来自「不安的地穴」。", "各種金屬的靴子和護手：在鐵砧上鍛造（各 1 塊錠），在護甲鋪裡和頭盔擺在一起出售。Dawnplate 也有：靴子來自「朝聖之路」，護手來自「不安的地穴」。", "Ủng và găng giáp bằng mọi kim loại, rèn trên đe (mỗi món một thỏi) và bán cạnh mũ giáp ở các tiệm giáp. Dawnplate cũng có: ủng từ Con đường hành hương, găng giáp từ Hầm mộ không yên.", "Sepatu bot dan sarung tangan zirah dari setiap logam, ditempa di landasan (masing-masing satu batangan) dan dijual di samping helm di toko zirah. Dawnplate juga punya: sepatu bot dari Jalan Peziarah, sarung tangan dari Kripta yang Gelisah.", "รองเท้าบูตและถุงมือเกราะทุกโลหะ ตีที่ทั่ง (ชิ้นละหนึ่งแท่ง) และขายคู่กับหมวกเกราะในร้านเกราะ Dawnplate ก็มี: รองเท้าบูตจากเส้นทางผู้แสวงบุญ ถุงมือเกราะจากสุสานใต้ดินที่ไม่สงบ", "Her metalden botlar ve eldivenler; örste dövülür (her biri bir külçe) ve zırhçılarda miğferlerin yanında satılır. Dawnplate'te de var: botlar Hacı Yolu'ndan, eldivenler Huzursuz Mahzen'den.", "Botas y guanteletes de todos los metales, forjados en el yunque (un lingote cada uno) y a la venta junto a los yelmos en las armerías. Dawnplate también los tiene: las botas de El camino del peregrino y los guanteletes de La cripta inquieta.", "Botas e manoplas de todos os metais, forjadas na bigorna (uma barra cada) e vendidas ao lado dos elmos nos arsenais. A Dawnplate também tem: botas de A Estrada do Peregrino e manoplas de A Cripta Inquieta.", "Сапоги и латные перчатки из всех металлов: куются на наковальне (по одному слитку) и продаются рядом со шлемами в оружейных. Есть и в Dawnplate: сапоги за «Дорогу паломника», перчатки за «Беспокойный склеп».", "Чоботи й латні рукавиці з усіх металів: куються на ковадлі (по одному злитку) і продаються поруч зі шоломами в зброярнях. Є й у Dawnplate: чоботи за «Дорогу прочанина», рукавиці за «Неспокійний склеп»."],
  "Boots, gloves and gauntlets show on your Friend, along with the rest of your armour.": ["ブーツ、手袋、籠手もほかの防具と一緒にフレンドに表示されます。", "장화, 장갑, 건틀릿이 나머지 갑옷과 함께 프렌드에게 보입니다.", "靴子、手套和护手会和其他盔甲一起显示在伙伴身上。", "靴子、手套和護手會和其他盔甲一起顯示在夥伴身上。", "Ủng, găng tay và găng giáp hiện trên Bạn của bạn, cùng phần giáp còn lại.", "Sepatu bot, sarung tangan, dan sarung tangan zirah tampak pada Sahabatmu, bersama sisa zirahmu.", "รองเท้าบูต ถุงมือ และถุงมือเกราะแสดงบนเพื่อนของคุณ พร้อมกับเกราะชิ้นอื่น", "Botlar, eldivenler ve zırh eldivenleri zırhının geri kalanıyla birlikte Dostunda görünüyor.", "Las botas, los guantes y los guanteletes se ven en tu Amigo, junto al resto de la armadura.", "Botas, luvas e manoplas aparecem no seu Amigo, junto com o resto da armadura.", "Сапоги, перчатки и латные перчатки видны на Друге вместе с остальными доспехами.", "Чоботи, рукавички й латні рукавиці видно на Другові разом з іншими обладунками."],
  "Helms fit your Friend's head, following its outline, and four-legged Friends wear chest plates as barding over the back instead of shoulder plates up by the head.": ["兜はフレンドの頭の輪郭に沿ってぴったり合い、四本足のフレンドは胸当てを頭の近くの肩当てではなく、背中を覆う馬鎧として身につけます。", "투구가 프렌드 머리 윤곽을 따라 꼭 맞고, 네발 프렌드는 흉갑을 머리 옆 어깨 갑옷이 아니라 등을 덮는 마갑으로 입습니다.", "头盔会贴合伙伴头部的轮廓，四足伙伴则把胸甲当作覆盖背部的马铠来穿，而不是靠近头部的肩甲。", "頭盔會貼合夥伴頭部的輪廓，四足夥伴則把胸甲當作覆蓋背部的馬鎧來穿，而不是靠近頭部的肩甲。", "Mũ giáp vừa với đầu Bạn, theo đường viền của nó, và Bạn bốn chân mặc giáp ngực như giáp ngựa phủ lưng thay vì giáp vai cạnh đầu.", "Helm pas di kepala Sahabatmu, mengikuti garis tepinya, dan Sahabat berkaki empat memakai zirah dada sebagai baju zirah kuda di punggung, bukan pelindung bahu di dekat kepala.", "หมวกเกราะพอดีกับหัวเพื่อน ตามโครงร่าง และเพื่อนสี่ขาสวมเกราะอกเป็นเกราะม้าคลุมหลังแทนเกราะไหล่ใกล้หัว", "Miğferler Dostunun başına, hatlarını izleyerek oturuyor; dört ayaklı Dostlar göğüslükleri baş yanındaki omuzluklar yerine sırtı örten at zırhı olarak giyiyor.", "Los yelmos se ajustan a la cabeza de tu Amigo siguiendo su contorno, y los Amigos de cuatro patas llevan la coraza como barda sobre el lomo en lugar de hombreras junto a la cabeza.", "Os elmos se ajustam à cabeça do seu Amigo, seguindo o contorno, e Amigos de quatro patas usam a couraça como barda sobre as costas em vez de ombreiras junto à cabeça.", "Шлемы сидят по контуру головы Друга, а четвероногие Друзья носят кирасы как конскую броню на спине, а не наплечники у головы.", "Шоломи сидять по контуру голови Друга, а чотириногі Друзі носять кіраси як кінську броню на спині, а не наплічники біля голови."],
  "Cleaner world: health bars in fights only, High by default, whole helms": ["すっきりした世界：体力バーは戦闘中のみ、高画質が標準、一体型の兜", "더 깔끔한 세상: 체력 바는 전투 중에만, 기본은 높음, 통짜 투구", "更清爽的世界：血条只在战斗中显示、默认高画质、完整的头盔", "更清爽的世界：血條只在戰鬥中顯示、預設高畫質、完整的頭盔", "Thế giới gọn gàng hơn: thanh máu chỉ khi đánh nhau, mặc định Cao, mũ giáp liền khối", "Dunia lebih bersih: bar nyawa hanya saat bertarung, Tinggi sebagai bawaan, helm utuh", "โลกที่สะอาดตาขึ้น: แถบพลังชีวิตเฉพาะตอนต่อสู้ ค่าเริ่มต้นเป็นสูง หมวกเกราะชิ้นเดียว", "Daha temiz bir dünya: can çubukları yalnızca dövüşte, varsayılan Yüksek, bütün miğferler", "Un mundo más limpio: barras de vida solo en combate, Alto por defecto y yelmos enteros", "Mundo mais limpo: barras de vida só em lutas, Alto por padrão e elmos inteiros", "Мир почище: полоски здоровья только в бою, высокая графика по умолчанию, цельные шлемы", "Чистіший світ: смужки здоров'я лише в бою, висока графіка за замовчуванням, цільні шоломи"],
  "Health bars only show while something is fighting: monsters when they're attacking you, you're attacking them, another player is fighting them or they've just been hit; yours and other players' in combat. (A monster's level is still in its right-click menu.)": ["体力バーは何かが戦っているときだけ表示されます：モンスターは、あなたを攻撃しているとき、あなたが攻撃しているとき、ほかのプレイヤーと戦っているとき、または攻撃を受けた直後。あなたやほかのプレイヤーのものは戦闘中。（モンスターのレベルは右クリックメニューで確認できます。）", "체력 바는 무언가 싸울 때만 보입니다: 몬스터는 당신을 공격할 때, 당신이 공격할 때, 다른 플레이어가 싸울 때, 방금 맞았을 때. 당신과 다른 플레이어의 것은 전투 중일 때. (몬스터 레벨은 여전히 우클릭 메뉴에 있습니다.)", "血条只在有东西战斗时显示：怪物在攻击你、你在攻击它、其他玩家在打它或它刚被打中时；你和其他玩家的血条在战斗中显示。（怪物等级仍在其右键菜单中。）", "血條只在有東西戰鬥時顯示：怪物在攻擊你、你在攻擊牠、其他玩家在打牠或牠剛被打中時；你和其他玩家的血條在戰鬥中顯示。（怪物等級仍在其右鍵選單中。）", "Thanh máu chỉ hiện khi có gì đang đánh nhau: quái vật khi chúng tấn công bạn, bạn tấn công chúng, người chơi khác đánh chúng hoặc chúng vừa trúng đòn; của bạn và người chơi khác khi đang chiến đấu. (Cấp của quái vật vẫn ở menu chuột phải.)", "Bar nyawa hanya tampak saat ada yang bertarung: monster saat menyerangmu, kamu menyerangnya, pemain lain melawannya, atau baru saja terkena; milikmu dan pemain lain saat bertarung. (Level monster masih ada di menu klik kanannya.)", "แถบพลังชีวิตแสดงเฉพาะตอนมีการต่อสู้: มอนสเตอร์เมื่อโจมตีคุณ คุณโจมตีมัน ผู้เล่นอื่นสู้กับมัน หรือเพิ่งโดนตี ของคุณและผู้เล่นอื่นเมื่ออยู่ในการต่อสู้ (เลเวลมอนสเตอร์ยังอยู่ในเมนูคลิกขวา)", "Can çubukları yalnızca bir şey dövüşürken görünüyor: canavarlar sana saldırırken, sen onlara saldırırken, başka bir oyuncu onlarla dövüşürken ya da az önce vurulduklarında; seninki ve diğer oyuncularınki dövüşteyken. (Bir canavarın seviyesi hâlâ sağ tık menüsünde.)", "Las barras de vida solo se ven mientras algo está luchando: los monstruos cuando te atacan, cuando tú los atacas, cuando otro jugador los combate o justo después de recibir un golpe; la tuya y la de otros jugadores en combate. (El nivel de un monstruo sigue en su menú de clic derecho.)", "As barras de vida só aparecem enquanto algo está lutando: monstros quando estão atacando você, você está atacando eles, outro jogador está lutando com eles ou acabaram de levar um golpe; a sua e a de outros jogadores em combate. (O nível de um monstro ainda aparece no menu do clique direito.)", "Полоски здоровья видны только во время боя: у монстров — когда они атакуют вас, вы атакуете их, с ними сражается другой игрок или их только что ударили; ваша и других игроков — в бою. (Уровень монстра по-прежнему в меню правого клика.)", "Смужки здоров'я видно лише під час бою: у монстрів — коли вони атакують вас, ви атакуєте їх, із ними б'ється інший гравець або їх щойно вдарили; ваша й інших гравців — у бою. (Рівень монстра й далі в меню правого кліку.)"],
  "Graphics are High by default and never change by themselves; choose Low in Settings if you want it.": ["グラフィックは標準で高、勝手に変わることはありません。低にしたい場合は設定で選んでください。", "그래픽은 기본이 높음이고 저절로 바뀌지 않습니다. 원하면 설정에서 낮음을 고르세요.", "图形默认为高，并且不会自行改变；如需低画质请在设置中选择。", "圖形預設為高，並且不會自行改變；如需低畫質請在設定中選擇。", "Đồ họa mặc định là Cao và không bao giờ tự đổi; chọn Thấp trong Cài đặt nếu bạn muốn.", "Grafis bawaan Tinggi dan tak pernah berubah sendiri; pilih Rendah di Pengaturan bila mau.", "กราฟิกเริ่มต้นเป็นสูงและไม่เปลี่ยนเอง เลือกต่ำในการตั้งค่าถ้าต้องการ", "Grafikler varsayılan olarak Yüksek ve asla kendiliğinden değişmiyor; istersen Ayarlar'dan Düşük'ü seç.", "Los gráficos están en Alto por defecto y nunca cambian solos; elige Bajo en Ajustes si lo prefieres.", "Os gráficos são Altos por padrão e nunca mudam sozinhos; escolha Baixo nas Configurações se quiser.", "Графика по умолчанию высокая и сама никогда не меняется; выберите низкую в настройках, если нужно.", "Графіка за замовчуванням висока й сама ніколи не змінюється; оберіть низьку в налаштуваннях, якщо потрібно."],
  "Helms are one shell from every side: open at the face with a nose guard from the front, turned with you from the side, and closed with a ridge from behind.": ["兜はどの方向から見ても一体の殻に：正面からは顔が開いて鼻当てがあり、横からはあなたと一緒に向きを変え、後ろからは稜線のある閉じた形に。", "투구는 어느 쪽에서 봐도 하나의 껍데기입니다: 앞에선 얼굴이 트이고 코 가리개가 있고, 옆에선 당신과 함께 돌며, 뒤에선 능선이 있는 닫힌 모양.", "头盔从各个方向看都是一体的：正面露脸并带护鼻，侧面随你转动，背面封闭并带一道脊。", "頭盔從各個方向看都是一體的：正面露臉並帶護鼻，側面隨你轉動，背面封閉並帶一道脊。", "Mũ giáp là một khối liền từ mọi phía: hở mặt với miếng che mũi từ phía trước, xoay theo bạn khi nhìn từ bên, và kín có gờ khi nhìn từ sau.", "Helm adalah satu cangkang dari segala sisi: terbuka di wajah dengan pelindung hidung dari depan, berputar bersamamu dari samping, dan tertutup dengan rusuk dari belakang.", "หมวกเกราะเป็นชิ้นเดียวทุกด้าน: เปิดที่หน้าพร้อมที่กันจมูกจากด้านหน้า หันตามคุณจากด้านข้าง และปิดมีสันจากด้านหลัง", "Miğferler her yönden tek bir kabuk: önden yüzü açık ve burunluklu, yandan seninle dönüyor, arkadan sırtlı ve kapalı.", "Los yelmos son una sola pieza desde cualquier lado: abiertos en la cara con nasal por delante, girando contigo de lado y cerrados con una cresta por detrás.", "Os elmos são uma peça só de qualquer lado: abertos no rosto com protetor de nariz pela frente, girando com você de lado e fechados com uma crista por trás.", "Шлемы — цельная скорлупа с любой стороны: спереди открыты для лица и с наносником, сбоку поворачиваются вместе с вами, сзади закрыты и с гребнем.", "Шоломи — цільна шкаралупа з будь-якого боку: спереду відкриті для обличчя й з наносником, збоку повертаються разом із вами, ззаду закриті й з гребенем."],
  "Dressed-up townsfolk": ["おしゃれな町の人々", "멋 부린 마을 사람들", "盛装的镇民", "盛裝的鎮民", "Dân thị trấn ăn diện", "Warga kota berdandan", "ชาวเมืองแต่งตัว", "Süslenmiş kasaba halkı", "Gente del pueblo bien vestida", "O povo da cidade bem vestido", "Нарядные горожане", "Ошатні городяни"],
  "Villagers wear their own hats (wizard's points, feathered caps, traveller's hats, hoods), some wear capes in every colour and pattern, a few an amulet, and some carry an axe or a pickaxe. Each keeps their look.": ["村人たちはそれぞれの帽子をかぶり（とんがりの魔法使い帽、羽根付き帽子、旅人帽、フード）、ある人はあらゆる色と柄のマントを、数人はアミュレットを身につけ、斧やつるはしを持つ人もいます。それぞれの装いは変わりません。", "마을 사람들이 각자 모자를 씁니다(뾰족한 마법사 모자, 깃털 모자, 여행자 모자, 두건). 몇몇은 온갖 색과 무늬의 망토를, 몇몇은 부적을 걸치고, 도끼나 곡괭이를 든 이도 있습니다. 각자 모습이 유지됩니다.", "村民们戴着各自的帽子（尖顶巫师帽、羽毛帽、旅行帽、兜帽），有些披着各种颜色和图案的披风，少数戴着护符，还有人扛着斧头或镐。每个人的装扮都保持不变。", "村民們戴著各自的帽子（尖頂巫師帽、羽毛帽、旅行帽、兜帽），有些披著各種顏色和圖案的披風，少數戴著護符，還有人扛著斧頭或鎬。每個人的裝扮都保持不變。", "Dân làng đội mũ riêng (mũ phù thủy nhọn, mũ gắn lông, mũ lữ khách, mũ trùm), có người khoác áo choàng đủ màu đủ họa tiết, vài người đeo bùa hộ mệnh, và có người mang rìu hay cuốc chim. Mỗi người giữ vẻ ngoài riêng.", "Penduduk desa memakai topi masing-masing (topi runcing penyihir, topi berbulu, topi pengelana, tudung), sebagian memakai jubah segala warna dan pola, beberapa memakai jimat, dan ada yang membawa kapak atau beliung. Masing-masing mempertahankan tampilannya.", "ชาวบ้านสวมหมวกของตัวเอง (หมวกพ่อมดปลายแหลม หมวกประดับขน หมวกนักเดินทาง ฮู้ด) บางคนสวมผ้าคลุมทุกสีทุกลาย บางคนห้อยเครื่องราง และบางคนถือขวานหรือจอบ แต่ละคนคงลุคของตัว", "Köylüler kendi şapkalarını takıyor (sivri büyücü şapkaları, tüylü kasketler, yolcu şapkaları, kapüşonlar); bazıları her renk ve desende pelerin, birkaçı muska takıyor, bazıları balta ya da kazma taşıyor. Herkes kendi görünüşünü koruyor.", "Los aldeanos llevan sus propios sombreros (puntiagudos de mago, gorras con pluma, sombreros de viajero, capuchas), algunos capas de todos los colores y diseños, unos pocos un amuleto, y otros llevan un hacha o un pico. Cada uno conserva su aspecto.", "Os aldeões usam seus próprios chapéus (pontudos de mago, bonés com pena, chapéus de viajante, capuzes), alguns usam capas de todas as cores e padrões, poucos um amuleto, e alguns carregam um machado ou uma picareta. Cada um mantém o visual.", "Жители носят собственные шляпы (остроконечные колпаки волшебников, шапочки с пером, шляпы путников, капюшоны), кто-то — плащи всех цветов и узоров, некоторые — амулеты, а кто-то носит топор или кирку. Каждый сохраняет свой облик.", "Мешканці носять власні капелюхи (гострі ковпаки чарівників, шапочки з пером, капелюхи мандрівників, каптури), хтось — плащі всіх кольорів і візерунків, дехто — амулети, а хтось носить сокиру чи кайло. Кожен зберігає свій вигляд."],
  "Townsfolk dress for their trades: the old miner and the mountain guide carry pickaxes, Axel and the Fernwick foresters axes, the fisher and the miller wear straw hats, and Tamsin the tailor is the best dressed of all.": ["町の人々は仕事に合わせた装い：年寄りの鉱夫と山岳ガイドはつるはし、アクセルとファーンウィックの森番は斧を持ち、漁師と粉屋は麦わら帽子、仕立て屋の Tamsin は誰よりもおしゃれです。", "마을 사람들이 직업에 맞게 차려입습니다: 늙은 광부와 산악 안내인은 곡괭이를, 악셀과 펀윅 산지기들은 도끼를 들고, 어부와 방앗간 주인은 밀짚모자를 쓰며, 재단사 Tamsin이 가장 잘 차려입었습니다.", "镇民按职业打扮：老矿工和山地向导扛着镐，阿克塞尔和蕨村的林务员扛着斧头，渔夫和磨坊主戴着草帽，裁缝 Tamsin 穿得最讲究。", "鎮民按職業打扮：老礦工和山地嚮導扛著鎬，阿克塞爾和蕨村的林務員扛著斧頭，漁夫和磨坊主戴著草帽，裁縫 Tamsin 穿得最講究。", "Dân thị trấn ăn mặc theo nghề: lão thợ mỏ và người dẫn đường núi mang cuốc chim, Axel và các người giữ rừng Fernwick mang rìu, người đánh cá và người xay bột đội mũ rơm, còn thợ may Tamsin ăn mặc đẹp nhất.", "Warga kota berpakaian sesuai pekerjaan: penambang tua dan pemandu gunung membawa beliung, Axel dan penjaga hutan Fernwick membawa kapak, nelayan dan penggiling memakai topi jerami, dan Tamsin si penjahit paling rapi dari semua.", "ชาวเมืองแต่งตัวตามอาชีพ: คนงานเหมืองชราและไกด์ภูเขาถือจอบ แอกเซลและคนดูแลป่าแห่งเฟิร์นวิกถือขวาน ชาวประมงและคนโม่แป้งสวมหมวกฟาง และช่างตัดเสื้อ Tamsin แต่งตัวดีที่สุด", "Kasaba halkı mesleklerine göre giyiniyor: yaşlı madenci ve dağ rehberi kazma, Axel ve Fernwick ormancıları balta taşıyor, balıkçı ve değirmenci hasır şapka takıyor ve terzi Tamsin en şık giyineni.", "La gente del pueblo viste según su oficio: el viejo minero y el guía de montaña llevan picos, Axel y los guardabosques de Fernwick hachas, el pescador y el molinero sombreros de paja, y Tamsin la sastra es la mejor vestida de todos.", "O povo da cidade se veste pelo ofício: o velho mineiro e o guia de montanha carregam picaretas, Axel e os guardas-florestais de Fernwick machados, o pescador e o moleiro usam chapéus de palha, e Tamsin, a alfaiate, é a mais bem vestida de todos.", "Горожане одеваются по ремеслу: старый шахтёр и горный проводник носят кирки, Аксель и лесничие Фернвика — топоры, рыбак и мельник — соломенные шляпы, а портной Tamsin одет лучше всех.", "Городяни вдягаються за ремеслом: старий шахтар і гірський провідник носять кайла, Аксель і лісничі Фернвіка — сокири, рибалка й мельник — солом'яні капелюхи, а кравець Tamsin вдягнений найкраще."],
  "More villagers about in Fernwick, the Frostpeak camp and Highcairn.": ["ファーンウィック、フロストピークの野営地、ハイケアンに村人が増えました。", "펀윅, 프로스트피크 야영지, 하이케언에 마을 사람이 늘었습니다.", "蕨村、霜峰营地和高冢有了更多村民。", "蕨村、霜峰營地和高塚有了更多村民。", "Thêm dân làng ở Fernwick, trại Frostpeak và Highcairn.", "Lebih banyak penduduk di Fernwick, perkemahan Frostpeak, dan Highcairn.", "ชาวบ้านมากขึ้นในเฟิร์นวิก ค่ายฟรอสต์พีก และไฮแคร์น", "Fernwick'te, Frostpeak kampında ve Highcairn'de daha çok köylü var.", "Más aldeanos por Fernwick, el campamento de Frostpeak y Highcairn.", "Mais aldeões por Fernwick, o acampamento de Frostpeak e Highcairn.", "Больше жителей во Фернвике, лагере Фростпика и Хайкэрне.", "Більше мешканців у Фернвіку, таборі Фростпіку та Гайкерні."],
  "Dawnplate, three Order quests, armour you can see, and smoother graphics": ["Dawnplate、騎士団クエスト3つ、見える鎧、なめらかなグラフィック", "Dawnplate, 기사단 퀘스트 셋, 보이는 갑옷, 더 매끄러운 그래픽", "Dawnplate、三个骑士团任务、看得见的盔甲与更流畅的画面", "Dawnplate、三個騎士團任務、看得見的盔甲與更流暢的畫面", "Dawnplate, ba nhiệm vụ của Dòng, giáp nhìn thấy được và đồ họa mượt hơn", "Dawnplate, tiga misi Ordo, zirah yang terlihat, dan grafis lebih mulus", "Dawnplate เควสต์ภาคีสามเควสต์ เกราะที่มองเห็น และกราฟิกที่ลื่นขึ้น", "Dawnplate, üç Tarikat görevi, görülebilen zırh ve daha akıcı grafikler", "Dawnplate, tres misiones de la Orden, armaduras visibles y gráficos más fluidos", "Dawnplate, três missões da Ordem, armaduras visíveis e gráficos mais suaves", "Dawnplate, три квеста Ордена, видимые доспехи и плавная графика", "Dawnplate, три квести Ордену, видимі обладунки й плавніша графіка"],
  "Three new quests for the Order of the Dawn. The Pilgrim's Road (Sister Maren, Faith 35): pray at the Realm's three old altars. The Restless Crypt (Faith 45): lay twelve crypt skeletons to rest with a faith weapon. Dawn Against the Hollow (Grandmaster Aldric, Faith 60, after The Hollow King): destroy five Hollow sentinels with a faith weapon and bring three Hollow essence to seal their gate.": ["Order of the Dawn の新クエストが3つ。「巡礼の道」（シスター・マーレン、信仰35）：レルムの3つの古い祭壇で祈る。「眠らぬ地下墓所」（信仰45）：信仰の武器で地下墓所の骸骨12体を眠りにつかせる。「虚ろに抗う夜明け」（総長アルドリック、信仰60、「虚ろの王」のあと）：信仰の武器で虚ろの番兵5体を倒し、虚ろの精髄3つを持ち帰って門を封じる。", "Order of the Dawn의 새 퀘스트 셋. '순례자의 길'(마렌 수녀, 신앙 35): 렐름의 오래된 제단 세 곳에서 기도하세요. '잠들지 못하는 지하묘지'(신앙 45): 신앙 무기로 지하묘지 해골 열둘을 잠재우세요. '공허에 맞선 새벽'(그랜드마스터 앨드릭, 신앙 60, '공허의 왕' 이후): 신앙 무기로 공허 파수병 다섯을 쓰러뜨리고 공허의 정수 셋을 가져와 그들의 문을 봉인하세요.", "Order of the Dawn 的三个新任务。「朝圣之路」（玛伦修女，信仰 35）：在王国三座古老的祭坛祈祷。「不安的地穴」（信仰 45）：用信仰武器让十二具地穴骷髅安息。「黎明对抗空洞」（大团长奥尔德里克，信仰 60，需完成「空洞之王」）：用信仰武器摧毁五个虚空哨兵，并带回三份虚空精华封印它们的门。", "Order of the Dawn 的三個新任務。「朝聖之路」（瑪倫修女，信仰 35）：在王國三座古老的祭壇祈禱。「不安的地穴」（信仰 45）：用信仰武器讓十二具地穴骷髏安息。「黎明對抗空洞」（大團長奧爾德里克，信仰 60，需完成「空洞之王」）：用信仰武器摧毀五個虛空哨兵，並帶回三份虛空精華封印它們的門。", "Ba nhiệm vụ mới cho Order of the Dawn. Con đường hành hương (Sơ Maren, Đức tin 35): cầu nguyện ở ba bàn thờ cổ của Vương quốc. Hầm mộ không yên (Đức tin 45): cho mười hai bộ xương hầm mộ yên nghỉ bằng vũ khí đức tin. Bình minh chống lại Hư không (Đại sư Aldric, Đức tin 60, sau Vua Hư không): tiêu diệt năm lính canh Hư không bằng vũ khí đức tin và mang ba tinh chất hư không để phong ấn cổng của chúng.", "Tiga misi baru untuk Order of the Dawn. Jalan Peziarah (Suster Maren, Iman 35): berdoa di tiga altar tua Realm. Kripta yang Gelisah (Iman 45): istirahatkan dua belas kerangka kripta dengan senjata iman. Fajar Melawan Hampa (Grandmaster Aldric, Iman 60, setelah Raja Hampa): hancurkan lima penjaga Hampa dengan senjata iman dan bawa tiga esensi hampa untuk menyegel gerbang mereka.", "เควสต์ใหม่สามเควสต์ของ Order of the Dawn เส้นทางผู้แสวงบุญ (ซิสเตอร์มาเรน ศรัทธา 35): สวดที่แท่นบูชาเก่าสามแห่งของอาณาจักร สุสานใต้ดินที่ไม่สงบ (ศรัทธา 45): ส่งโครงกระดูกในสุสานสิบสองตัวให้สงบด้วยอาวุธศรัทธา รุ่งอรุณต้านความว่างเปล่า (ปรมาจารย์อัลดริก ศรัทธา 60 หลังราชาแห่งความว่างเปล่า): ทำลายผู้เฝ้ายามแห่งความว่างเปล่าห้าตัวด้วยอาวุธศรัทธา และนำแก่นความว่างเปล่าสามชิ้นมาผนึกประตูของพวกมัน", "Order of the Dawn için üç yeni görev. Hacı Yolu (Rahibe Maren, İnanç 35): Diyar'ın üç eski sunağında dua et. Huzursuz Mahzen (İnanç 45): on iki mahzen iskeletini bir inanç silahıyla huzura kavuştur. Boşluğa Karşı Şafak (Büyük Üstat Aldric, İnanç 60, Boşluk Kralı'ndan sonra): beş Boşluk nöbetçisini bir inanç silahıyla yok et ve kapılarını mühürlemek için üç Boşluk özü getir.", "Tres misiones nuevas para la Order of the Dawn. El camino del peregrino (hermana Maren, Fe 35): reza en los tres altares antiguos del Reino. La cripta inquieta (Fe 45): da descanso a doce esqueletos de la cripta con un arma de fe. El Alba contra el Vacío (Gran maestre Aldric, Fe 60, tras El Rey del Vacío): destruye cinco centinelas del Hueco con un arma de fe y lleva tres esencias huecas para sellar su puerta.", "Três missões novas para a Order of the Dawn. A Estrada do Peregrino (Irmã Maren, Fé 35): reze nos três altares antigos do Reino. A Cripta Inquieta (Fé 45): dê descanso a doze esqueletos da cripta com uma arma de fé. Aurora contra o Vazio (Grão-mestre Aldric, Fé 60, depois de O Rei do Vazio): destrua cinco sentinelas do Oco com uma arma de fé e traga três essências ocas para selar o portão delas.", "Три новых квеста Order of the Dawn. «Дорога паломника» (сестра Марен, Вера 35): помолитесь у трёх древних алтарей Королевства. «Беспокойный склеп» (Вера 45): упокойте двенадцать скелетов склепа оружием веры. «Рассвет против Пустоты» (Великий магистр Олдрик, Вера 60, после «Короля Пустоты»): уничтожьте пять стражей Пустоты оружием веры и принесите три эссенции пустоты, чтобы запечатать их врата.", "Три нові квести Order of the Dawn. «Дорога прочанина» (сестра Марен, Віра 35): помоліться біля трьох давніх вівтарів Королівства. «Неспокійний склеп» (Віра 45): упокойте дванадцять скелетів склепу зброєю віри. «Світанок проти Порожнечі» (Великий магістр Олдрік, Віра 60, після «Короля Порожнечі»): знищте п'ять вартових Порожнечі зброєю віри й принесіть три есенції порожнечі, щоб запечатати їхню браму."],
  "Dawnplate, the Order's gold armour with white trim (Defence 70, Faith 60): greaves, helm and shield, and the cuirass for Dawn Against the Hollow. Each quest's pieces are sold in the Order Armoury once you've earned them.": ["Dawnplate、白い縁取りの騎士団の金の鎧（防御70、信仰60）：すね当て、兜、盾、そして「虚ろに抗う夜明け」の胸当て。各クエストの部位は、獲得すると Order Armoury で売られるようになります。", "Dawnplate, 흰 테두리가 있는 기사단의 금빛 갑옷(방어 70, 신앙 60): 정강이받이, 투구, 방패, 그리고 '공허에 맞선 새벽'의 흉갑. 각 퀘스트의 부위는 얻고 나면 Order Armoury에서 팝니다.", "Dawnplate，骑士团的白边金甲（防御 70，信仰 60）：护胫、头盔和盾牌，以及「黎明对抗空洞」的胸甲。每个任务的部件在你获得后会在 Order Armoury 出售。", "Dawnplate，騎士團的白邊金甲（防禦 70，信仰 60）：護脛、頭盔和盾牌，以及「黎明對抗空洞」的胸甲。每個任務的部件在你獲得後會在 Order Armoury 出售。", "Dawnplate, bộ giáp vàng viền trắng của Dòng (Phòng thủ 70, Đức tin 60): giáp chân, mũ giáp và khiên, cùng giáp ngực cho Bình minh chống lại Hư không. Mỗi phần của nhiệm vụ được bán ở Order Armoury khi bạn đã đạt được.", "Dawnplate, zirah emas Ordo bertepi putih (Pertahanan 70, Iman 60): pelindung kaki, helm, dan perisai, serta zirah dada untuk Fajar Melawan Hampa. Bagian tiap misi dijual di Order Armoury setelah kau mendapatkannya.", "Dawnplate เกราะทองขลิบขาวของภาคี (ป้องกัน 70 ศรัทธา 60): สนับแข้ง หมวกเกราะ และโล่ และเกราะอกสำหรับรุ่งอรุณต้านความว่างเปล่า ชิ้นส่วนของแต่ละเควสต์ขายที่ Order Armoury เมื่อคุณได้รับแล้ว", "Dawnplate, Tarikat'ın beyaz şeritli altın zırhı (Savunma 70, İnanç 60): dizlikler, miğfer ve kalkan, ayrıca Boşluğa Karşı Şafak için göğüslük. Her görevin parçaları kazandıktan sonra Order Armoury'de satılıyor.", "Dawnplate, la armadura dorada con ribete blanco de la Orden (Defensa 70, Fe 60): grebas, yelmo y escudo, y la coraza de El Alba contra el Vacío. Las piezas de cada misión se venden en la Order Armoury una vez las hayas ganado.", "Dawnplate, a armadura dourada com acabamento branco da Ordem (Defesa 70, Fé 60): grevas, elmo e escudo, e a couraça de Aurora contra o Vazio. As peças de cada missão são vendidas na Order Armoury quando você as conquista.", "Dawnplate — золотые доспехи Ордена с белой отделкой (Защита 70, Вера 60): поножи, шлем и щит, а также кираса за «Рассвет против Пустоты». Части каждого квеста продаются в Order Armoury, когда вы их заслужите.", "Dawnplate — золоті обладунки Ордену з білим оздобленням (Захист 70, Віра 60): наголінники, шолом і щит, а також кіраса за «Світанок проти Порожнечі». Частини кожного квесту продаються в Order Armoury, коли ви їх заслужите."],
  "Armour shows on your Friend: cuirasses as breastplates with shoulder plates, vests and robes, and greaves on your legs. Helms are closed at the back now, and the castle guards and knights of the Dawn wear their armour too.": ["鎧がフレンドに表示されるように：胸当ては肩当て付きの胸甲、ベスト、ローブとして、すね当ては脚に。兜は後ろが閉じた形になり、城の衛兵や暁の騎士も鎧を着ています。", "갑옷이 프렌드에게 보입니다: 흉갑은 어깨 갑옷이 달린 가슴판, 조끼, 로브로, 정강이받이는 다리에. 투구는 이제 뒤가 막혀 있고, 성 경비병과 여명 기사들도 갑옷을 입습니다.", "盔甲会显示在伙伴身上：胸甲表现为带肩甲的胸铠、背心和长袍，护胫穿在腿上。头盔现在背面是封闭的，城堡守卫和黎明骑士也穿着各自的盔甲。", "盔甲會顯示在夥伴身上：胸甲表現為帶肩甲的胸鎧、背心和長袍，護脛穿在腿上。頭盔現在背面是封閉的，城堡守衛和黎明騎士也穿著各自的盔甲。", "Giáp hiện trên Bạn của bạn: giáp ngực như tấm che ngực có giáp vai, áo gi lê và áo choàng dài, và giáp chân trên chân. Mũ giáp giờ kín phía sau, và lính gác lâu đài cùng hiệp sĩ Bình Minh cũng mặc giáp.", "Zirah tampak pada Sahabatmu: zirah dada sebagai pelindung dada dengan pelindung bahu, rompi, dan jubah, serta pelindung kaki di kakimu. Helm kini tertutup di belakang, dan penjaga kastel serta ksatria Fajar juga memakai zirah mereka.", "เกราะแสดงบนเพื่อนของคุณ: เกราะอกเป็นแผ่นอกพร้อมเกราะไหล่ เสื้อกั๊ก และเสื้อคลุม และสนับแข้งที่ขา หมวกเกราะตอนนี้ปิดด้านหลัง และยามปราสาทกับอัศวินรุ่งอรุณก็สวมเกราะด้วย", "Zırh Dostunda görünüyor: göğüslükler omuzluklu göğüs zırhı, yelek ve cüppe olarak, dizlikler bacaklarında. Miğferler artık arkadan kapalı; kale muhafızları ve Şafak şövalyeleri de zırhlarını giyiyor.", "La armadura se ve en tu Amigo: corazas como petos con hombreras, chalecos y túnicas, y grebas en las piernas. Los yelmos ahora están cerrados por detrás, y los guardias del castillo y los caballeros del Alba también llevan su armadura.", "A armadura aparece no seu Amigo: couraças como peitorais com ombreiras, coletes e mantos, e grevas nas pernas. Os elmos agora são fechados atrás, e os guardas do castelo e os cavaleiros da Aurora também usam suas armaduras.", "Доспехи видны на Друге: кирасы — как нагрудники с наплечниками, жилеты и мантии, а поножи — на ногах. Шлемы теперь закрыты сзади, а стражники замка и рыцари Зари тоже носят доспехи.", "Обладунки видно на Другові: кіраси — як нагрудники з наплічниками, жилети й мантії, а наголінники — на ногах. Шоломи тепер закриті ззаду, а вартові замку й лицарі Світанку теж носять обладунки."],
  "Your settings are remembered in this browser. High and Low stay as you set them; only Auto adjusts itself, and on a slow high-DPI screen it first draws fewer pixels (keeping the lighting) before it tries Low.": ["設定はこのブラウザに記憶されます。高と低は設定したまま変わらず、自動だけが自ら調整します。遅い高DPI画面では、低を試す前にまず描画ピクセルを減らします（ライティングは維持）。", "설정이 이 브라우저에 기억됩니다. 높음과 낮음은 설정한 그대로 유지되고, 자동만 스스로 조절하며, 느린 고DPI 화면에선 낮음을 시도하기 전에 먼저 픽셀을 덜 그립니다(조명은 유지).", "你的设置会记在这个浏览器里。高和低保持你设定的样子；只有自动会自我调整，在较慢的高 DPI 屏幕上，它会先减少绘制的像素（保留光照），再尝试低画质。", "你的設定會記在這個瀏覽器裡。高和低保持你設定的樣子；只有自動會自我調整，在較慢的高 DPI 螢幕上，它會先減少繪製的像素（保留光照），再嘗試低畫質。", "Cài đặt của bạn được ghi nhớ trong trình duyệt này. Cao và Thấp giữ nguyên như bạn đặt; chỉ Tự động tự điều chỉnh, và trên màn hình DPI cao chậm, nó vẽ ít pixel hơn trước (giữ ánh sáng) rồi mới thử Thấp.", "Pengaturanmu diingat di peramban ini. Tinggi dan Rendah tetap seperti yang kau atur; hanya Otomatis yang menyesuaikan diri, dan di layar DPI tinggi yang lambat ia menggambar lebih sedikit piksel dulu (mempertahankan pencahayaan) sebelum mencoba Rendah.", "การตั้งค่าของคุณถูกจำไว้ในเบราว์เซอร์นี้ สูงและต่ำคงตามที่ตั้ง มีแค่อัตโนมัติที่ปรับเอง และบนจอ DPI สูงที่ช้า มันจะวาดพิกเซลน้อยลงก่อน (คงแสงไว้) แล้วค่อยลองต่ำ", "Ayarların bu tarayıcıda hatırlanıyor. Yüksek ve Düşük ayarladığın gibi kalıyor; yalnızca Otomatik kendini ayarlıyor ve yavaş bir yüksek DPI ekranda Düşük'ü denemeden önce daha az piksel çiziyor (aydınlatmayı koruyarak).", "Tus ajustes se recuerdan en este navegador. Alto y Bajo se quedan como los pongas; solo Auto se ajusta solo, y en una pantalla de alta densidad lenta primero dibuja menos píxeles (manteniendo la iluminación) antes de probar Bajo.", "Suas configurações ficam lembradas neste navegador. Alto e Baixo ficam como você deixou; só o Auto se ajusta sozinho, e numa tela de alta densidade lenta ele primeiro desenha menos pixels (mantendo a iluminação) antes de tentar o Baixo.", "Настройки запоминаются в этом браузере. Высокая и низкая остаются такими, как вы выбрали; подстраивается только Авто, и на медленном экране с высоким DPI она сначала рисует меньше пикселей (сохраняя освещение), а потом пробует низкую.", "Налаштування запам'ятовуються в цьому браузері. Висока й низька лишаються такими, як ви вибрали; підлаштовується лише Авто, і на повільному екрані з високим DPI вона спершу малює менше пікселів (зберігаючи освітлення), а потім пробує низьку."],
  "High draws at up to 1.5× on high-DPI screens (the pixel art looks the same, with about half the pixels of 2× to light), and the lighting's hidden passes skip the ink outlines, so laptops run it more smoothly. Cached art is kept least-recently-used, with less of it.": ["高画質は高DPI画面で最大1.5倍で描画し（ピクセルアートの見た目は同じで、照らすピクセルは2倍時の約半分）、ライティングの隠れた処理はインクの輪郭線を省くので、ノートパソコンでもなめらかに動きます。キャッシュしたアートは最近使っていないものから捨てられ、量も減りました。", "높음은 고DPI 화면에서 최대 1.5배로 그리며(픽셀 아트는 똑같아 보이고, 비출 픽셀은 2배의 절반 정도), 조명의 숨은 단계가 잉크 외곽선을 건너뛰어 노트북에서 더 매끄럽게 돌아갑니다. 캐시된 아트는 가장 오래 안 쓴 것부터 버리고, 양도 줄었습니다.", "高画质在高 DPI 屏幕上最多以 1.5 倍绘制（像素画看起来一样，需要照亮的像素约为 2 倍时的一半），光照的隐藏步骤跳过墨线描边，因此笔记本运行更流畅。缓存的图像按最近最少使用保留，数量也更少。", "高畫質在高 DPI 螢幕上最多以 1.5 倍繪製（像素畫看起來一樣，需要照亮的像素約為 2 倍時的一半），光照的隱藏步驟跳過墨線描邊，因此筆電執行更流暢。快取的圖像按最近最少使用保留，數量也更少。", "Cao vẽ tối đa 1,5× trên màn hình DPI cao (pixel art trông như cũ, với khoảng một nửa số pixel cần chiếu sáng so với 2×), và các lượt ẩn của ánh sáng bỏ qua đường viền mực, nên laptop chạy mượt hơn. Hình đã lưu đệm được giữ theo kiểu ít dùng gần đây nhất, và ít hơn.", "Tinggi menggambar hingga 1,5× di layar DPI tinggi (seni pikselnya tampak sama, dengan sekitar setengah piksel 2× untuk diterangi), dan proses tersembunyi pencahayaan melewatkan garis tinta, jadi laptop menjalankannya lebih mulus. Gambar tembolok disimpan berdasarkan yang paling lama tak dipakai, dengan jumlah lebih sedikit.", "กราฟิกสูงวาดได้สูงสุด 1.5× บนจอ DPI สูง (พิกเซลอาร์ตดูเหมือนเดิม โดยมีพิกเซลให้ส่องแสงราวครึ่งหนึ่งของ 2×) และขั้นตอนแสงที่ซ่อนอยู่ข้ามเส้นขอบหมึก แล็ปท็อปจึงลื่นขึ้น ภาพแคชเก็บแบบใช้ล่าสุดน้อยที่สุดและเก็บน้อยลง", "Yüksek, yüksek DPI ekranlarda 1,5 kata kadar çiziyor (piksel sanatı aynı görünüyor, aydınlatılacak piksel 2 katın yaklaşık yarısı) ve aydınlatmanın gizli geçişleri mürekkep çizgilerini atlıyor, böylece dizüstüler daha akıcı çalışıyor. Önbellekteki görseller en az yakın zamanda kullanılana göre tutuluyor ve daha az.", "Alto dibuja hasta 1,5× en pantallas de alta densidad (el pixel art se ve igual, con la mitad de píxeles que iluminar que a 2×), y las pasadas ocultas de la iluminación omiten los contornos de tinta, así que los portátiles lo mueven con más fluidez. El arte en caché se guarda por uso menos reciente, y en menor cantidad.", "O Alto desenha até 1,5× em telas de alta densidade (o pixel art fica igual, com cerca de metade dos pixels de 2× para iluminar), e as passagens ocultas da iluminação pulam os contornos de tinta, então notebooks rodam mais suave. A arte em cache é mantida por uso menos recente, e em menor quantidade.", "Высокая рисует до 1,5× на экранах с высоким DPI (пиксель-арт выглядит так же, а освещать нужно примерно вдвое меньше пикселей, чем при 2×), а скрытые проходы освещения пропускают чернильные контуры, так что на ноутбуках игра идёт плавнее. Кэш графики хранится по принципу «давно не использовалось — удаляется», и его меньше.", "Висока малює до 1,5× на екранах із високим DPI (піксель-арт виглядає так само, а освітлювати треба приблизно вдвічі менше пікселів, ніж при 2×), а приховані проходи освітлення пропускають чорнильні контури, тож на ноутбуках гра йде плавніше. Кеш графіки зберігається за принципом «давно не використовувалося — видаляється», і його менше."],
};
